const PANE = 'crew-graph'
const TITLE = 'Crew'
const PANE_COLUMNS = 70
const WEB_FILES = [
  'index.html',
  'app.js',
  'three.min.js',
  'THREE_LICENSE.txt',
  'gltf-loader.classic.js',
  'characters-core.js',
  'characters.js',
