]
const WEB_THROTTLE_MS = 450


// ---------------------------------------------------------------- state

const meta = atom({ plugin: 'crew-graph', key: 'meta' } as const, { schemaVersion: SCHEMA_VERSION })
const main = atom({ plugin: 'crew-graph', key: 'main' } as const, DEFAULT_MAIN)
const usage = atom({ plugin: 'crew-graph', key: 'usage' } as const, DEFAULT_USAGE)
const architect = atom({ plugin: 'crew-graph', key: 'architect' } as const, DEFAULT_ARCHITECT)
const gate = atom({ plugin: 'crew-graph', key: 'gate' } as const, DEFAULT_GATE)
const agents = atom({ plugin: 'crew-graph', key: 'agents' } as const, [])
const loops = atom({ plugin: 'crew-graph', key: 'loops' } as const, [])
const log = atom({ plugin: 'crew-graph', key: 'log' } as const, [])
const turn = atom({ plugin: 'crew-graph', key: 'turn' } as const, DEFAULT_TURN)
const receipt = atom({ plugin: 'crew-graph', key: 'receipt' } as const, null)
const view = atom({ plugin: 'crew-graph', key: 'view' } as const, DEFAULT_VIEW)
const roster = atom({ plugin: 'crew-graph', key: 'roster' } as const, DEFAULT_ROSTER)
const acts = atom({ plugin: 'crew-graph', key: 'acts' } as const, {})
const files = atom({ plugin: 'crew-graph', key: 'files' } as const, [])
const events = atom({ plugin: 'crew-graph', key: 'events' } as const, [])
const parents = atom({ plugin: 'crew-graph', key: 'parents' } as const, {})
const tasks = atom({ plugin: 'crew-graph', key: 'tasks' } as const, { todo: [], task: [], turn: [], mail: [], assign: [], eaten: {} })
const setup = atom({ plugin: 'crew-graph', key: 'setup' } as const, { native: null })
const autoOpened = atom({ plugin: 'crew-graph', key: 'autoOpened' } as const, false)
const web = atom({ plugin: 'crew-graph', key: 'web' } as const, { isOn: false, dir: '', lastWriteAt: 0 })
const view3d = atom({ plugin: 'crew-graph', key: 'view3d' } as const, { isOn: false, cols: 0, rows: 0, status: '' })
const petFocus = atom({ plugin: 'crew-graph', key: 'petFocus' } as const, null)
const sessionTitle = atom({ plugin: 'crew-graph', key: 'sessionTitle' } as const, '')
const dismissed = atom({ plugin: 'crew-graph', key: 'dismissed' } as const, {})
const lastReply = atom({ plugin: 'crew-graph', key: 'lastReply' } as const, null)
const petOn = atom({ plugin: 'crew-graph', key: 'petOn' } as const, false)
const paneRows = atom({ plugin: 'crew-graph', key: 'paneRows' } as const, 0)

type ServerBlock = { type: string; id?: string; name?: string; tool_use_id?: string }

// Every read goes through these, so a value saved under an older shape still reads.
async function getMain($: EngineInterface): Promise<Main> {
  return normalize(DEFAULT_MAIN, await read($, main))
}
async function getUsage($: EngineInterface): Promise<Usage> {
  return normalize(DEFAULT_USAGE, await read($, usage))
}
async function getArchitect($: EngineInterface): Promise<Architect> {
  const a = normalize(DEFAULT_ARCHITECT, await read($, architect))
  return { ...a, consults: listOf(a.consults), ids: listOf(a.ids), seen: listOf(a.seen) }
}
async function getGate($: EngineInterface): Promise<Gate> {
  return normalizeGate(await read($, gate))
}
async function getCards($: EngineInterface): Promise<AgentCard[]> {
  return listOf<unknown>(await read($, agents)).map(normalizeCard)
}
async function getLoops($: EngineInterface): Promise<Loop[]> {
  return listOf<Loop>(await read($, loops))
}
async function getLog($: EngineInterface): Promise<LogLine[]> {
  return normalizeLog(await read($, log))
}
async function getTurn($: EngineInterface): Promise<Turn> {
  return normalize(DEFAULT_TURN, await read($, turn))
}
async function getView($: EngineInterface): Promise<View> {
  return normalize(DEFAULT_VIEW, await read($, view))
}
async function getRoster($: EngineInterface): Promise<Roster> {
  const r = normalize(DEFAULT_ROSTER, await read($, roster))
  return { architectTypes: listOf(r.architectTypes) }
}

/** A stored shape older than this build's: drop what cannot be read, keep the rest. */
async function migrate($: EngineInterface) {
  const m = await read($, meta)
  if ((m?.schemaVersion ?? 0) >= SCHEMA_VERSION) return
  await update($, log, list => normalizeLog(list))
  await update($, agents, list => listOf<unknown>(list).map(normalizeCard))
  await update($, gate, g => normalizeGate(g))
  await update($, meta, () => ({ schemaVersion: SCHEMA_VERSION }))
}

async function say($: EngineInterface, who: string, text: string, kind: LogLine['kind'] = 'info', agentId: string | null = null) {
  const line: LogLine = { at: await $.clock.now(), who, text, kind, agentId }
  await update($, log, list => [...normalizeLog(list), line].slice(-60))
}

async function refreshStatus($: EngineInterface, cfg: Config) {
  if (!cfg.statusLine) return $.ui.status(undefined)
  const [u, a, g, allCards, dis, ac] = await Promise.all([getUsage($), getArchitect($), getGate($), getCards($), getDismissed($), getActs($)])
  const hidden = hiddenIds(allCards, dis, ac)
  const cards = allCards.filter(c => !hidden.has(c.id))
  const running = cards.filter(c => c.status === 'running').length
  const s = gateSummary(g)
  const parts = [
    u.pct !== null ? `ctx ${Math.round(u.pct)}%` : null,
    cards.length > 0 ? `agents ${running}/${cards.length}` : null,
    a.consults.length > 0 || a.ids.length > 0 ? `${cfg.architectLabel.toLowerCase()} ${isAdvising(a) ? 'advising' : a.consults.length}` : null,
    s.deny > 0 ? `denied ${s.deny}` : null,
  ]
  // Only fields with something to say; with none, no status entry at all.
  const shown = parts.filter(Boolean)
  $.ui.status(shown.length > 0 ? shown.join(' · ') : undefined)
}

async function whoIs($: EngineInterface, agentId: string | undefined) {
  if (!agentId) return 'main'
  const card = (await getCards($)).find(c => c.id === agentId)
  return card ? shorten(cardTitle(card), 14) : 'agent'
}

async function consultStarted($: EngineInterface, cfg: Config, id: string, via: string) {
  const t = await getTurn($)
  const moment = momentOf(t)
  const at = await $.clock.now()
  await update($, architect, a => startConsult(normalize(DEFAULT_ARCHITECT, a), { id, at, moment, via }))
  if (moment === 'before done') await update($, turn, x => ({ ...normalize(DEFAULT_TURN, x), isReviewing: true }))
  await say($, cfg.architectLabel.toLowerCase(), cfg.moments ? `${moment} · ${via}` : `consulted · ${via}`, 'consult')
  await refreshStatus($, cfg)
}

async function consultEnded($: EngineInterface, cfg: Config, advice: string | null, id?: string) {
  const at = await $.clock.now()
  const first = advice?.split('\n').find(l => l.trim()) ?? null
  const text = first ? shorten(first.replace(/^[#>*\s-]+/, ''), 160) : null
  await update($, architect, a => endConsult(normalize(DEFAULT_ARCHITECT, a), at, text, id))
  await update($, turn, t => ({ ...normalize(DEFAULT_TURN, t), isReviewing: false }))
  await say($, cfg.architectLabel.toLowerCase(), text ? `advice: ${shorten(text, 60)}` : 'advice returned', 'consult')
  await refreshStatus($, cfg)
}

async function noteAdvice($: EngineInterface, cfg: Config, advice: string) {
  await update($, architect, x => ({ ...normalize(DEFAULT_ARCHITECT, x), lastAdvice: advice }))
  await say($, cfg.architectLabel.toLowerCase(), `advice: ${shorten(advice, 60)}`, 'consult')
}

async function isArchitectType($: EngineInterface, cfg: Config, type: string) {
  return cfg.architect.test(type) || (await getRoster($)).architectTypes.includes(type)
}

async function openPane($: EngineInterface) {
  // columns apply when docked beside the transcript, rows when seated inline above the prompt.
  return $.ui.open({ id: PANE, title: TITLE, columns: PANE_COLUMNS, rows: 8 })
}

async function resetAll($: EngineInterface) {
  await update($, main, m => ({ ...DEFAULT_MAIN, model: normalize(DEFAULT_MAIN, m).model, mode: normalize(DEFAULT_MAIN, m).mode }))
  await update($, architect, () => DEFAULT_ARCHITECT)
  await update($, gate, () => DEFAULT_GATE)
  await update($, agents, () => [])
  await update($, loops, () => [])
  await update($, log, () => [])
  await update($, turn, () => DEFAULT_TURN)
  await update($, receipt, () => null)
  await update($, view, () => DEFAULT_VIEW)
  await update($, acts, () => ({}))
  await update($, files, () => [])
  await update($, events, () => [])
  await update($, parents, () => ({}))
  await update($, tasks, () => ({ todo: [], task: [], turn: [], mail: [], assign: [], eaten: {} }))
  turnQueue.length = 0
  mailWaits.length = 0
  mailFroms = []
  await update($, sessionTitle, () => '')
  // The dismissed set belongs to the agents that were just cleared; a pending question to the pet is not answered any more.
  await update($, dismissed, () => ({}))
  await update($, lastReply, () => null)
  askWaits.length = 0
  askTurns.clear()
  // The context gauge waits for the next measurement rather than showing the pre-clear fill.
  await update($, usage, x => ({ ...normalize(DEFAULT_USAGE, x), pct: null, tokens: null }))
}

/** The session's cost read fresh, not from the last measurement: the receipt subtracts two of these. */
async function costNow($: EngineInterface): Promise<number | null> {
  const u = await $.session.usage().catch(() => null)
  return u?.cost?.usd ?? null
}

async function noteMode($: EngineInterface, mode: string | undefined) {
  if (mode) await update($, main, m => (normalize(DEFAULT_MAIN, m).mode === mode ? normalize(DEFAULT_MAIN, m) : { ...normalize(DEFAULT_MAIN, m), mode }))
}

// ---------------------------------------------------------------- food from: which task tools the session has, and the prompt turns as proxy food
// A model without TodoWrite / TaskCreate leaves the agents' to-dos out of the food; each prompt the user sends (main's turn) is food instead.
// The subagent tickets are in every session. hooks/setup.ts has the rules, hooks/tasks.ts the items.

/** The `foodFrom` option. */
let foodFrom: FoodFrom = 'auto'
/** Prompts typed while a turn runs, in line: the id of the pending item and the head of the text, to match the turn that starts for it. */
const turnQueue: { qid: string; key: string }[] = []
let queueSeq = 0
const QUEUE_KEY_LEN = 80
const QUEUE_MAX = 20

async function getSetup($: EngineInterface): Promise<SetupState> {
  return normalize({ native: null } as SetupState, await read($, setup))
}

/** Does the session list a native task tool? true / false, null when the list cannot be read. */
async function detectNative($: EngineInterface): Promise<boolean | null> {
  try {
    return hasNativeTaskTools((await $.tool.list()).map(t => t.name))
  } catch {
    return null
  }
}

/** The state, reading the tool list when that has not worked yet. */
async function knownSetup($: EngineInterface): Promise<SetupState> {
  const s = await getSetup($)
  if (s.native !== null) return s
  const native = await detectNative($)
  if (native === null) return s
  await update($, setup, () => ({ native }))
  return { native }
}

/** Are the prompt turns food now? */
async function proxyOn($: EngineInterface) {
  // only `auto` depends on the tool list
  if (foodFrom !== 'auto') return proxyFoodOn(foodFrom, null)
  return proxyFoodOn(foodFrom, (await knownSetup($)).native)
}

/** A native task tool was used: the session has them, whatever the tool list said. */
async function noteNativeSeen($: EngineInterface) {
  if ((await getSetup($)).native !== true) await update($, setup, () => ({ native: true }))
}

/** A prompt typed over a running turn waits behind it: a pending item on main's plate, until its own turn starts. */
async function noteTurnQueued($: EngineInterface, text: string) {
  const now = await $.clock.now()
  queueSeq += 1
  const qid = `q${queueSeq}`
  turnQueue.push({ qid, key: text.slice(0, QUEUE_KEY_LEN) })
  if (turnQueue.length > QUEUE_MAX) turnQueue.shift()
  await update($, tasks, b => applyTurnQueued(normalizeBook(b), qid, text, now))
  await queueWeb($)
}

/**
 * Main's turn starts: a prompt of the user's (or a question typed into the pet, titled by the user's words, not the frame) is an item in
 * progress; a turn the engine opened with a tagged message (a hand-back, a task notification) is not. A queued prompt's pending item becomes it.
 * A turn opened by a letter never gets here (noteMailStart took it, by the origin its prompt carried); the text check is the fallback for a
 * turn whose origin was not seen.
 */
async function noteTurnStart($: EngineInterface, turnId: string, text: string, askKey: string) {
  if (!(askKey || (text.trim() && looksLikeUser(text)))) return
  const now = await $.clock.now()
  const title = askKey || text
  let at = turnQueue.findIndex(q => text.includes(q.key) || title.includes(q.key))
  // The line runs in order: a user turn that matches no text is the head of it (a pet question never came from the line).
  if (at < 0 && !askKey && turnQueue.length > 0) at = 0
  const queued = at >= 0 ? turnQueue.splice(at, 1)[0] : undefined
  await update($, tasks, b => applyTurnStart(normalizeBook(b), turnId, title, now, queued?.qid))
}

async function noteTurnEnd($: EngineInterface, turnId: string, reason: string) {
  const now = await $.clock.now()
  await update($, tasks, b => applyTurnEnd(normalizeBook(b), turnId, reason, now))
}

// ---------------------------------------------------------------- mail and assignments (the work queue; on whatever the food setting is)
// A letter is a message that reaches main from a teammate, a task or another session (the prompt's origin says so). It waits on main's plate
// and is eaten when the main turn that reads it ends. An assignment is a job main gave a teammate; the teammate holds it until it reports.

/** Letters that reached main and have not opened a turn yet, and the sightings of who sent what (hooks/tasks.ts). */
const mailWaits: MailWait[] = []
let mailFroms: MailFrom[] = []
let mailSeq = 0
const MAIL_WAIT_MAX = 20
const MAIL_WAIT_TTL_MS = 5 * 60_000

/** A letter reached main. Returns its id. Registered before the prompt goes on: the turn it opens starts inside that call. */
async function noteMailIn($: EngineInterface, text: string, kind: string, turnId: string | undefined): Promise<string> {
  const now = await $.clock.now()
  mailSeq += 1
  const mid = `${now.toString(36)}-${mailSeq}`
  const { from, summary } = mailParse(text, kind, mailFromOf(mailFroms, text, now))
  if (turnId === undefined) {
    mailWaits.push({ mid, key: mailKey(text), at: now })
    if (mailWaits.length > MAIL_WAIT_MAX) mailWaits.shift()
  }
  await update($, tasks, b => applyMailIn(normalizeBook(b), mid, mailTitle(from, summary), now, turnId))
  await queueWeb($)
  return mid
}

/** The prompt of a letter was dropped by another hook: the letter never reached main. */
async function noteMailDrop($: EngineInterface, mid: string) {
  const at = mailWaits.findIndex(w => w.mid === mid)
  if (at >= 0) mailWaits.splice(at, 1)
  await update($, tasks, b => applyMailDrop(normalizeBook(b), mid))
  await queueWeb($)
}

/** Main's turn starts: the letter that opened it (if one did) is its work. Returns whether a letter opened it. */
async function noteMailStart($: EngineInterface, turnId: string, text: string): Promise<boolean> {
  const now = await $.clock.now()
  for (let i = mailWaits.length - 1; i >= 0; i -= 1) if (now - (mailWaits[i]?.at ?? now) > MAIL_WAIT_TTL_MS) mailWaits.splice(i, 1)
  const wait = mailForTurn(mailWaits, text)
  if (wait) mailWaits.splice(mailWaits.indexOf(wait), 1)
  await update($, tasks, b => applyMailStart(normalizeBook(b), turnId, now, wait?.mid))
  return wait !== undefined
}

async function noteMailEnd($: EngineInterface, turnId: string, reason: string) {
  const now = await $.clock.now()
  await update($, tasks, b => applyMailEnd(normalizeBook(b), turnId, reason, now))
}

/** Cards already checked against the engine's agent list this load, so the list is asked for once per card. */
const matesChecked = new Set<string>()

/**
 * A card made before this version has no `isTeammate`; the engine's agent list knows (`teammateId` is there for a teammate and for no other agent).
 * The flag is written back, so the card stops being a ticket and its idle flips stop being eaten. Returns the cards, flags settled.
 */
async function settleTeammates($: EngineInterface, rows?: readonly { id: string; teammateId?: string }[]): Promise<AgentCard[]> {
  let cards = await getCards($)
  const todo = cards.filter(c => !c.isTeammate && !matesChecked.has(c.id))
  if (todo.length === 0) return cards
  const list = rows ?? (await $.agent.list().catch(() => null))
  if (!list) return cards
  const mates = new Set(todo.filter(c => list.some(r => r.id === c.id && r.teammateId)).map(c => c.id))
  for (const c of todo) matesChecked.add(c.id)
  if (mates.size === 0) return cards
  await update($, agents, l => listOf<unknown>(l).map(normalizeCard).map(c => (mates.has(c.id) ? { ...c, isTeammate: true } : c)))
  cards = await getCards($)
  return cards
}

/** A message left an agent for another: main giving a teammate a job, or a teammate reporting to the lead. */
async function noteSend($: EngineInterface, from: string | undefined, to: unknown, text: string) {
  if (typeof to !== 'string') return
  const listed = await $.agent.list().catch(() => null)
  const rows = listed ?? []
  const cards = await settleTeammates($, listed ?? undefined)
  const target = addresseeOf(to, [...rows.map(r => ({ id: r.id, name: r.name, teammateId: r.teammateId })), ...cards.map(c => ({ id: c.id, name: c.type }))])
  const mate = (id: string) => cards.find(c => c.id === id)?.isTeammate === true
  const now = await $.clock.now()
  if (from === undefined) {
    if (target && mate(target)) await update($, tasks, b => applyAssign(normalizeBook(b), target, assignTitle(undefined, text), 'main', now))
  } else if (mate(from) && !target) {
    // a teammate's message to the lead is its report: the oldest job it holds is handed back
    mailFroms = noteMailFrom(mailFroms, text, cards.find(c => c.id === from)?.type ?? '', now)
    await update($, tasks, b => applyAssignDone(normalizeBook(b), from, false, now))
  } else return
  await queueWeb($)
}

// ---------------------------------------------------------------- crew

let cwd = ''
/** The `characters` option as [who, character] pairs, for the snapshot. */
let charRules: [string, string][] = []
let webPending = false
const WEB_OFF: Web = { isOn: false, dir: '', lastWriteAt: 0 }

async function getActs($: EngineInterface): Promise<Record<string, LoopAct>> {
  const a = await read($, acts)
  return a && typeof a === 'object' ? a : {}
}
async function getFiles($: EngineInterface): Promise<FileNode[]> {
  return listOf<FileNode>(await read($, files))
}
async function getEvents($: EngineInterface): Promise<CrewEvent[]> {
  return listOf<CrewEvent>(await read($, events))
}
async function getParents($: EngineInterface): Promise<Record<string, string>> {
  const p = await read($, parents)
  return p && typeof p === 'object' ? p : {}
}
async function getDismissed($: EngineInterface): Promise<Record<string, string>> {
  return dismissedOf(await read($, dismissed))
}
async function getWeb($: EngineInterface): Promise<Web> {
  return normalize(WEB_OFF, await read($, web))
}

/** TodoWrite, TaskCreate and TaskUpdate: what the agent `key` just said about its tasks (hooks/tasks.ts keeps the book). */
async function noteTasks($: EngineInterface, e: Record<string, unknown>, ran: { result?: unknown; text?: unknown }, key: string) {
  const now = await $.clock.now()
  const tool = String(e.tool)
  if (tool === 'TodoWrite') await update($, tasks, b => applyTodoWrite(normalizeBook(b), key, e, now))
  else if (tool === 'TaskCreate') {
    const id = createdId(ran.result, ran.text)
    if (id) await update($, tasks, b => applyTaskCreate(normalizeBook(b), id, e, now))
  } else {
    const known = [{ id: 'main', type: 'main' }, ...(await getCards($)).map(c => ({ id: c.id, type: c.type }))]
    await update($, tasks, b => applyTaskUpdate(normalizeBook(b), e, key, known, now))
  }
  await queueWeb($)
}

async function act($: EngineInterface, key: string, verb: Verb, tool: string, target: string) {
  const now = await $.clock.now()
  await update($, acts, all => {
    const prev = all?.[key]
    return { ...all, [key]: { key, verb, tool, target, since: now, calls: (prev?.calls ?? 0) + (tool ? 1 : 0) } }
  })
}

async function emit($: EngineInterface, e: Omit<CrewEvent, 'id' | 't'>) {
  const t = await $.clock.now()
  await update($, events, list => pushEvent(listOf<CrewEvent>(list), { ...e, t }))
  await queueWeb($)
}

/** The browser view's data, written at most every WEB_THROTTLE_MS while the export is on. */
async function queueWeb($: EngineInterface) {
  const w = await getWeb($)
  if (!w.isOn || webPending) return
  const now = await $.clock.now()
  const wait = Math.max(0, WEB_THROTTLE_MS - (now - w.lastWriteAt))
  if (wait === 0) return writeWeb($)
  webPending = true
  $.clock.after(wait, () => void flushWeb($))
}

async function flushWeb($: EngineInterface) {
  webPending = false
  await writeWeb($)
}

async function writeWeb($: EngineInterface) {
  const w = await getWeb($)
  if (!w.isOn || !w.dir) return
  const [m, u, a, g, allCards, t, r, allActs, allFiles, allEvents, allParents, now, sid, title, shown, reply, book] = await Promise.all([
    getMain($),
    getUsage($),
    getArchitect($),
    getGate($),
    settleTeammates($),
    getTurn($),
    read($, receipt),
    getActs($),
    getFiles($),
    getEvents($),
    getParents($),
    $.clock.now(),
    $.session.id().catch(() => ''),
    read($, sessionTitle),
    getDismissed($),
    read($, lastReply),
    read($, tasks),
  ])
  // Agents the pet dismissed are not in what the pet (or the browser) is shown.
  const hidden = hiddenIds(allCards, shown, allActs)
  const { cards, acts: ac, files: fl, events: ev, parents: pa } = withoutHidden(
    { cards: allCards, files: allFiles, acts: allActs, events: allEvents, parents: allParents },
    hidden,
  )
  // The prompt turns are food only while the proxies are on (see food from); the to-dos, tasks and tickets always are.
  const tk0 = normalizeBook(book)
  const tk = (await proxyOn($)) ? tk0 : { ...tk0, turn: [] }
  const snap = snapshotOf({
    now,
    sessionId: String(sid),
    title,
    cwd,
    main: m,
    usage: u,
    architect: a,
    gate: g,
    cards,
    architectIds: a.ids,
    acts: ac,
    files: fl,
    events: ev,
    parents: pa,
    turn: t,
    receipt: r,
    chars: charRules,
    lastReply: reply,
    ack: petAck,
    // a dismissed agent takes its tasks and its count with it
    tasks: tasksOf(tk, cards, pa, now, hidden),
    eaten: Object.fromEntries(Object.entries(tk.eaten).filter(([id]) => !hidden.has(id))),
  })
  const text = dataJs(snap)
  await $.fs.write(`${w.dir}/data.js`, text).catch(() => undefined)
  // The same snapshot under the session's own name: every desktop pet window reads its session's file, data.js is whoever wrote last.
  if (safeId(String(sid))) await $.fs.write(`${w.dir}/sessions/${sid}.js`, text).catch(() => undefined)
  await update($, web, x => ({ ...normalize(WEB_OFF, x), lastWriteAt: now }))
}

/** A session id that is fine as a file name (the usual uuid is). */
const safeId = (id: string) => /^[A-Za-z0-9._-]{1,80}$/.test(id)

async function homeDir($: EngineInterface) {
  return ((await $.env.get('USERPROFILE')) || (await $.env.get('HOME')) || '').replace(/\\/g, '/')
}

/** Copies the viewer next to its data and turns the export on; opens it in the browser when asked. */
async function startWeb($: EngineInterface, shouldOpen: boolean): Promise<string> {
  const home = await homeDir($)
  if (!home) return 'crew-graph: no home directory to write the browser view into.'
  const dir = `${home}/.claude/crew-graph`
  for (const f of WEB_FILES) {
    const text = await $.fs.read(`${$.plugin.root}/web/${f}`).catch(() => null)
    if (typeof text === 'string') await $.fs.write(`${dir}/${f}`, text)
  }
  await syncCharacters($, dir).catch(() => undefined)
  await update($, web, () => ({ isOn: true, dir, lastWriteAt: 0 }))
  await writeWeb($)
  const page = `${dir}/index.html`
  const where = shouldOpen ? await openInBrowser($, page) : ''
  return `Crew web view: ${page}${where}`
}

// ---------------------------------------------------------------- characters

const charFs = ($: EngineInterface): CharFs => ({
  list: p => $.fs.list(p),
  read: p => $.fs.read(p),
  readBytes: async p => (await $.fs.read(p, { as: 'bytes' })).base64,
  write: (p, t) => $.fs.write(p, t),
  exists: p => $.fs.exists(p),
})

/** Scans ~/.claude/crew-graph/characters/ and writes the manifest (and base64 parts of any GLB) the page loads. */
async function syncCharacters($: EngineInterface, dir: string): Promise<Scan> {
  const fs = charFs($)
  const folder = `${dir}/characters`
  await ensureCharacterFolder(fs, folder).catch(() => undefined)
  const scan = await scanCharacters(fs, folder, true)
  scan.at = await $.clock.now()
  await writeCharacters(fs, dir, scan)
  return scan
}

/** `/crew characters` lists; `/crew characters reload` rescans and rewrites what the page reads. */
async function charactersCommand($: EngineInterface, spec: string, reload: boolean): Promise<string> {
  const home = await homeDir($)
  if (!home) return 'crew-graph: no home directory to keep characters in.'
  const dir = `${home}/.claude/crew-graph`
  const scan = reload ? await syncCharacters($, dir) : await scanCharacters(charFs($), `${dir}/characters`, false)
  // What the pet's Settings window says (a missing or broken file is only reported) and what `auto` gives the agents of the latest snapshot.
  const petText = await $.fs.read(`${dir}/overlay/pet-settings.json`).catch(() => null)
  const sid = await petSession($)
  const snapText = (sid ? await $.fs.read(`${dir}/sessions/${sid}.js`).catch(() => null) : null) ?? (await $.fs.read(`${dir}/data.js`).catch(() => null))
  const pool = [...BUILTIN_CHARACTERS, ...scan.chars.map(c => ({ id: c.id, traits: c.kind === 'voxel' ? c.traits : [] }))]
  const extra = [
    ...describePetSettings(typeof petText === 'string' ? petText : null),
    ...describeAgentPicks(agentsFromDataJs(typeof snapText === 'string' ? snapText : null), pool),
  ]
  return describeCharacters(scan, spec, `${dir}/characters`, charRules, reload, extra)
}

/** Inside Orca, a browser tab beside the terminal (full pixels, real mouse); else the system browser. */
async function openInBrowser($: EngineInterface, page: string): Promise<string> {
  if ((await $.env.get('TERM_PROGRAM')) === 'Orca') {
    const url = `file://${page.startsWith('/') ? '' : '/'}${page}`
    const res = await $.process.run(['orca', 'tab', 'create', '--url', url, '--json'], { timeoutMs: 15_000 }).catch(() => null)
    if (res && res.exitCode === 0) return ' (opened in an Orca browser tab)'
  }
  const isWin = (await $.env.get('OS')) === 'Windows_NT'
  const argv = isWin ? ['explorer', page.replace(/\//g, '\\')] : [(await $.env.get('XDG_SESSION_TYPE')) ? 'xdg-open' : 'open', page]
  await $.process.run(argv, { timeoutMs: 10_000 }).catch(() => undefined)
  return ''
}

// ---------------------------------------------------------------- desktop pet
// overlay/main.js shows the web view in a transparent, always-on-top Electron window on the desktop. The mod
// cannot hold that process itself ($.process.spawn kills its child with the session), so overlay/launch.mjs starts
// it detached and returns. Electron lives in ~/.claude/crew-graph/overlay-runtime, not in the plugin folder
// (an update replaces that), and is installed with npm the first time.

const ELECTRON_VERSION = '44.4.5'
const PET_POLL_MS = 1000
/** One install at a time across sessions: a lock older than this is a crashed install, not a running one. */
const INSTALL_STALE_MS = 15 * 60_000
const INSTALL_WAIT_MS = 2000

const PET_HELP = [
  'Crew pet: the crabs on your desktop, with no background.',
  '  press a crab and pull to carry the window · shake it while carrying and it gets dizzy · click to pinch · stroke it (button up) to pet',
  '  right-drag to rotate · wheel to zoom · Ctrl+wheel or the corner grip to resize',
  '  click a file to open it · Shift+click shows it in the folder · right-click for the menu: Character (who is drawn as what), Settings…',
  '  the tray icon has Settings… too: characters per agent type or per agent, bubbles, ticker, papers, nameplate, reduced motion, opacity, size',
  '  the pill on top names this session (folder · first prompt); drag it to carry the window',
  '/crew pet off closes the window of this session, /crew pet off all every window.',
].join('\n')

type PetPaths = { dir: string; runtime: string; state: string; page: string; main: string; launch: string; isWin: boolean }

let petInstalling = false
// The poll of the pet's inbox runs while its generation is the current one; /crew pet off ends it.
let petGen = 0
let petSeen = 0
/**
 * Asked of the pet and the pet asks back with it: the secret this session gave the window it launched. Held in memory only (never in state
 * or the snapshot); the window repeats it in every request, and a request without it is ignored. A new one is made each time the pet is
 * started, which also hands it to a window that is already running.
 */
let petToken = ''
/** The newest request (its `seq`) this mod accepted; in the snapshot as `petAck`. Zero again after a reload: the requests of the old mod are not acknowledged. */
let petAck = 0
/** Questions sent from the pet that have not started their turn yet (the session may be busy): the head of the user's text. */
const askWaits: { key: string; at: number }[] = []
/** The ids of the main-loop turns that came from a pet question; the answer of such a turn is the pet's `lastReply`. */
const askTurns = new Set<string>()
const ASK_WAIT_MS = 30 * 60_000

async function petPaths($: EngineInterface): Promise<PetPaths | null> {
  const home = await homeDir($)
  if (!home) return null
  const dir = `${home}/.claude/crew-graph`
  // Test only: CREW_PET_RUNTIME names another folder to install Electron into (the default is overlay-runtime next to the viewer).
  const runtimeEnv = String((await $.env.get('CREW_PET_RUNTIME').catch(() => '')) ?? '').replace(/\\/g, '/')
  return {
    dir,
    runtime: runtimeEnv || `${dir}/overlay-runtime`,
    state: `${dir}/overlay`,
    page: `${dir}/index.html`,
    main: `${$.plugin.root}/overlay/main.js`,
    launch: `${$.plugin.root}/overlay/launch.mjs`,
    isWin: (await $.env.get('OS')) === 'Windows_NT',
  }
}

/** The Electron binary npm unpacked, if it is there: electron.exe, Electron.app on a Mac, else the bare binary. */
async function petElectron($: EngineInterface, p: PetPaths): Promise<string | null> {
  const base = `${p.runtime}/node_modules/electron/dist`
  const found = p.isWin
    ? [`${base}/electron.exe`]
    : [`${base}/Electron.app/Contents/MacOS/Electron`, `${base}/electron`]
  for (const f of found) if (await $.fs.exists(f).catch(() => false)) return f
  return null
}

const tailOf = (text: string) => text.trim().split('\n').slice(-6).join('\n').slice(-400)

type RunResult = { exitCode: number; stdout: string; stderr: string }
async function runOrFail($: EngineInterface, argv: readonly string[], cwd: string | undefined, timeoutMs: number): Promise<RunResult> {
  try {
    const r = await $.process.run(argv, cwd ? { cwd, timeoutMs } : { timeoutMs })
    return { exitCode: r.exitCode, stdout: r.stdout, stderr: r.stderr }
  } catch (e) {
    return { exitCode: 1, stdout: '', stderr: e instanceof Error ? e.message : String(e) }
  }
}

/** npm install electron@<pinned> into the runtime folder, then its own binary download (npm leaves that out here). '' when done. */
async function petInstall($: EngineInterface, p: PetPaths): Promise<string> {
  // Writing the folder's note makes the folder; npm makes the package.json itself.
  await $.fs.write(`${p.runtime}/README.txt`, 'Electron for the crew-graph desktop pet (/crew pet). Safe to delete: /crew pet installs it again.\n')
  // process.run has no shell, and npm is npm.cmd on Windows: go through cmd. --prefix . keeps it in this folder
  // (without it npm would look for a package.json in the folders above).
  const npm = p.isWin ? ['cmd', '/c', 'npm'] : ['npm']
  const got = await runOrFail($, [...npm, 'install', '--no-audit', '--no-fund', '--prefix', '.', `electron@${ELECTRON_VERSION}`], p.runtime, 600_000)
  if (got.exitCode !== 0) return `npm install electron@${ELECTRON_VERSION} failed: ${tailOf(got.stderr || got.stdout)}`
  const bin = await runOrFail($, ['node', 'node_modules/electron/install.js'], p.runtime, 600_000)
  if (bin.exitCode !== 0) return `the Electron binary download failed: ${tailOf(bin.stderr || bin.stdout)}`
  return ''
}

/** This session's id when it is usable in a file name, else '' (the pet then reads data.js, whoever wrote last). */
async function petSession($: EngineInterface): Promise<string> {
  const id = String(await $.session.id().catch(() => ''))
  return safeId(id) ? id : ''
}

async function petLaunch($: EngineInterface, p: PetPaths, bin: string): Promise<string> {
  const isOrca = (await $.env.get('TERM_PROGRAM')) === 'Orca'
  const sid = await petSession($)
  petToken = crypto.randomUUID().replace(/-/g, '')
  const argv = ['node', p.launch, '--electron', bin, '--main', p.main, '--page', p.page, '--state', p.state, ...(sid ? ['--session', sid, '--token', petToken] : []), ...(isOrca ? ['--orca'] : [])]
  const res = await runOrFail($, argv, undefined, 20_000)
  if (res.exitCode !== 0) return `crew pet: could not start it: ${tailOf(res.stdout || res.stderr)}`
  petWatch($, p, sid)
  return PET_HELP
}

async function toast($: EngineInterface, text: string) {
  try {
    await $.ui.toast(text)
  } catch {
    // a host without toasts just goes without
  }
}

async function petNotify($: EngineInterface, text: string) {
  await toast($, text)
  await say($, 'crew pet', text).catch(() => undefined)
}

const sleepFor = ($: EngineInterface, ms: number) => new Promise<void>(resolve => $.clock.after(ms, () => resolve()))

// The install lock is a file in the runtime folder: "held:<token>:<ms>" while an install runs, "free:<ms>" after. A session that starts
// while another installs waits for it (instead of running npm in the same folder), then opens its own window. The host has no
// delete, so a finished install writes "free"; a "held" older than INSTALL_STALE_MS is taken over.
const petLockFile = (p: PetPaths) => `${p.runtime}/install.lock`

async function petLockTake($: EngineInterface, p: PetPaths, token: string): Promise<boolean> {
  const now = await $.clock.now()
  const cur = await $.fs.read(petLockFile(p)).catch(() => null)
  const m = typeof cur === 'string' ? /^held:([^:]*):(\d+)/.exec(cur.trim()) : null
  if (m && now - Number(m[2]) < INSTALL_STALE_MS && m[1] !== token) return false
  await $.fs.write(petLockFile(p), `held:${token}:${now}`)
  // Two sessions can write at the same moment: the one whose token is still there after the write owns it.
  const back = await $.fs.read(petLockFile(p)).catch(() => null)
  return typeof back === 'string' && back.startsWith(`held:${token}:`)
}

async function petLockFree($: EngineInterface, p: PetPaths, token: string) {
  const cur = await $.fs.read(petLockFile(p)).catch(() => null)
  if (typeof cur === 'string' && !cur.startsWith(`held:${token}:`)) return // taken over after a long install: not ours to free
  await $.fs.write(petLockFile(p), `free:${await $.clock.now()}`).catch(() => undefined)
}

/** Installs Electron (one session at a time), then opens this session's window. Toasts: installing, then "ready" or the error. */
async function petInstallThenLaunch($: EngineInterface, p: PetPaths) {
  const token = `${await petSession($)}-${(await $.clock.now()).toString(36)}`
  let waited = false
  while (!(await petElectron($, p))) {
    if (await petLockTake($, p, token)) {
      await toast($, 'crew pet: installing Electron (~100 MB)… the pet opens by itself when it is done.')
      let err = ''
      try {
        err = await petInstall($, p)
      } finally {
        await petLockFree($, p, token)
      }
      if (err) return petNotify($, `crew pet: ${err}`)
      break
    }
    if (!waited) {
      waited = true
      await toast($, 'crew pet: another session is installing Electron; this one opens when it is done.')
    }
    await sleepFor($, INSTALL_WAIT_MS)
  }
  const bin = await petElectron($, p)
  if (!bin) return petNotify($, 'crew pet: npm finished but no Electron binary was found')
  const text = await petLaunch($, p, bin)
  await petNotify($, text === PET_HELP ? 'crew pet: ready' : text)
}

/** /crew pet: the viewer and its data, Electron, then the window. A first run installs Electron in the background. */
async function petStart($: EngineInterface): Promise<string> {
  await startWeb($, false)
  const p = await petPaths($)
  if (!p) return 'crew pet: no home directory to keep Electron in.'
  // The pet is on for this session: state outlives a reload, so session.start can start it again (new token, inbox poll) when it comes back.
  await update($, petOn, () => true)
  const bin = await petElectron($, p)
  if (bin) return petLaunch($, p, bin)
  if (petInstalling) return 'Electron is still downloading for the pet; it starts when that is done.'
  petInstalling = true
  void petInstallThenLaunch($, p)
    .catch(e => petNotify($, `crew pet: ${e instanceof Error ? e.message : String(e)}`))
    .finally(() => {
      petInstalling = false
    })
  return `Installing Electron ${ELECTRON_VERSION} (about 100 MB) for the pet, once, in ${p.runtime}. The pet opens by itself when that is done (a toast says so).`
}

/** /crew pet off closes this session's window, /crew pet off all quits the pet with every window. */
async function petStop($: EngineInterface, all: boolean): Promise<string> {
  petGen += 1
  petToken = ''
  await update($, petOn, () => false)
  const p = await petPaths($)
  if (!p) return 'crew pet: no home directory.'
  const sid = await petSession($)
  const which = all || !sid ? ['--quit'] : ['--close', sid]
  const res = await runOrFail($, ['node', p.launch, '--state', p.state, ...which], undefined, 10_000)
  if (res.exitCode !== 0) return `crew pet: could not ask it to close: ${tailOf(res.stdout || res.stderr)}`
  return which[0] === '--quit' ? 'Crew pet closed, with every window.' : "Crew pet: this session's window closed."
}

// The pet's right-click menu can ask the Crew pane to show a file or an agent: it writes <state>/pet-inbox.json
// and the mod looks at it about once a second while a pet it started is running.
type PetInbox = PetMsg & {
  abs?: string
  path?: string
  summary?: { title?: string; lead?: string; heads?: string[]; decls?: string[]; error?: string }
}

function petWatch($: EngineInterface, p: PetPaths, sid: string) {
  petGen += 1
  const gen = petGen
  const inbox = `${p.state}/${sid ? `pet-inbox-${sid}.json` : 'pet-inbox.json'}`
  void $.clock
    .now()
    .then(startedAt => petPoll($, gen, inbox, startedAt, 0))
    .catch(() => undefined)
}

/** Every this many polls the pet's settings are read again (auto-dismiss). */
const SETTINGS_EVERY = 10

async function petPoll($: EngineInterface, gen: number, inbox: string, startedAt: number, n: number) {
  if (gen !== petGen) return
  if (n % SETTINGS_EVERY === 0) await petAutoDismiss($, inbox.slice(0, inbox.lastIndexOf('/'))).catch(() => undefined)
  const text = await $.fs.read(inbox).catch(() => null)
  if (typeof text === 'string') {
    let msg: PetInbox | null = null
    try {
      msg = JSON.parse(text) as PetInbox
    } catch {
      msg = null
    }
    // Requests from before this pet started are not ours; one seq is acted on once.
    if (msg && typeof msg.seq === 'number' && msg.seq !== petSeen && (msg.at ?? 0) >= startedAt) {
      petSeen = msg.seq
      await petInbox($, msg).catch(() => undefined)
    }
  }
  if (gen === petGen) $.clock.after(PET_POLL_MS, () => void petPoll($, gen, inbox, startedAt, n + 1))
}

/** The pet's "auto-dismiss finished agents after N minutes": read from pet-settings.json (off when missing or unreadable), applied as a dismissal. */
async function petAutoDismiss($: EngineInterface, stateDir: string) {
  const minutes = autoDismissOf(await $.fs.read(`${stateDir}/pet-settings.json`).catch(() => null))
  if (minutes === 0) return
  const [cards, set, acts, now] = await Promise.all([getCards($), getDismissed($), getActs($), $.clock.now()])
  const next = autoDismissed(cards, set, acts, now, minutes)
  if (!next) return
  await update($, dismissed, () => next)
  await queueWeb($)
}

const FOCUS_LINES = 12

// ---------------------------------------------------------------- asking Claude from the pet, dismissing agents

async function petNote($: EngineInterface, text: string) {
  await say($, 'crew pet', text).catch(() => undefined)
}

/** Who a question is about: the card of an agent, or the main loop; null for a question with no agent or an id this session does not have. */
async function askAbout($: EngineInterface, id: string | undefined): Promise<AskAbout | null> {
  if (!id) return null
  const [cards, events, files, m] = await Promise.all([getCards($), getEvents($), getFiles($), getMain($)])
  if (id === 'main') return aboutOf({ id: 'main', type: 'main', status: m.isRunning ? 'running' : 'idle', description: 'the main loop of this session' }, events, files)
  const card = cards.find(c => c.id === id)
  return card ? aboutOf(card, events, files) : null
}

/**
 * An ask, a dismiss or a stop from the pet. It is acted on only with this session's id and the token the mod gave the pet. What reaches
 * the model is submitted framed (as a message of this plugin), never as the person's own words.
 */
async function petRequest($: EngineInterface, msg: PetInbox) {
  const checked = checkPetMsg(msg, await petSession($), petToken)
  if (!checked.ok) return petNote($, `ignored a pet ${String(msg.kind).slice(0, 12)} request: ${checked.why}`)
  // Received: the snapshot says so (`petAck`), which is how the pet knows a request got to a live mod. A request that is refused above gets none.
  if (typeof msg.seq === 'number') {
    petAck = Math.max(petAck, msg.seq)
    await queueWeb($)
  }
  if (msg.kind === 'ask') return petAsk($, msg)
  if (msg.kind === 'rescan') {
    // The Settings window's Rescan: the same as `/crew characters reload`; a running pet picks the new manifest up within a few seconds.
    const home = await homeDir($)
    if (home) await syncCharacters($, `${home}/.claude/crew-graph`).catch(() => undefined)
    return
  }
  if (msg.kind === 'dismiss') {
    const ids = Array.isArray(msg.ids) ? msg.ids.filter((x): x is string => typeof x === 'string' && x.length <= 200).slice(0, 100) : []
    const next = dismiss(await getDismissed($), ids, await getCards($), await getActs($))
    if (next.taken.length === 0) return
    await update($, dismissed, () => next.set)
    await queueWeb($)
    return
  }
  // stop: a running agent of this session, by id
  const card = typeof msg.id === 'string' ? (await getCards($)).find(c => c.id === msg.id) : undefined
  if (!card || isFinished(card)) return petNote($, 'ignored a pet stop request: that agent is not running')
  // $.agent has spawn, list and register only and $.turn.abort ends the main loop's turn: no call stops an agent, so the mod asks Claude to
  // (running TaskStop through $.tool.call would skip the person's chance to see the request; not done).
  void $.prompt.submit({ text: composeStop(card) }).catch(() => undefined)
}

async function petAsk($: EngineInterface, msg: PetInbox) {
  const text = cleanAsk(msg.text)
  if (!text) return petNote($, `ignored a pet question: empty or over ${ASK_MAX} characters`)
  if (msg.mode !== 'send' && msg.mode !== 'draft') return petNote($, 'ignored a pet question: no mode')
  const composed = composeAsk(text, await askAbout($, typeof msg.agentId === 'string' ? msg.agentId : undefined))
  if (msg.mode === 'draft') {
    // fill replaces the draft; a draft the person has typed already is kept, the question goes after it
    const box = await $.prompt.read().catch(() => null)
    const has = !!box && box.text.trim().length > 0
    await $.prompt.fill(has ? { text: `\n\n${composed}`, mode: 'append' } : { text: composed, mode: 'replace' }).catch(() => undefined)
    return
  }
  const now = await $.clock.now()
  const key = text.slice(0, 80)
  while (askWaits.length > 0 && now - (askWaits[0]?.at ?? now) > ASK_WAIT_MS) askWaits.shift()
  askWaits.push({ key, at: now })
  if (askWaits.length > 8) askWaits.shift()
  const forget = () => {
    const i = askWaits.findIndex(w => w.key === key && w.at === now)
    if (i >= 0) askWaits.splice(i, 1)
  }
  // Not awaited: the call returns when the turn has started, which may be after the current one. No `asUser`: the model reads it as this plugin's message.
  void $.prompt
    .submit({ text: composed })
    .then(r => {
      if ((r as { drop?: string }).drop !== undefined) forget()
    })
    .catch(forget)
}

async function petInbox($: EngineInterface, msg: PetInbox) {
  if (msg.kind === 'ask' || msg.kind === 'dismiss' || msg.kind === 'stop' || msg.kind === 'rescan') return petRequest($, msg)
  if (msg.kind === 'focus-agent' && typeof msg.id === 'string') {
    const id = msg.id
    if ((await getCards($)).some(c => c.id === id)) await update($, view, x => ({ ...normalize(DEFAULT_VIEW, x), expanded: id }))
    await openPane($)
    return
  }
  if (msg.kind !== 'focus-file' || typeof msg.abs !== 'string') return
  const abs = msg.abs
  // Only a file the crew itself touched: the inbox is a file anyone could write.
  const touched = (await getFiles($)).find(n => n.abs === abs)
  if (!touched) return
  const s = msg.summary
  const hasSummary = !!s && !s.error && (!!s.title || !!s.lead || !!s.heads?.length || !!s.decls?.length)
  let head: string[] = []
  if (!hasSummary) {
    const text = await $.fs.read(abs).catch(() => null)
    if (typeof text === 'string') head = text.split('\n').slice(0, FOCUS_LINES).map(l => clip(l.replace(/[\r\t]+/g, ' '), 100))
  }
  await update($, petFocus, () => ({
    kind: 'file' as const,
    abs,
    path: touched.path,
    summary: hasSummary && s ? { title: s.title ?? '', lead: s.lead ?? '', heads: s.heads ?? [], decls: s.decls ?? [] } : null,
    head,
    at: msg.at ?? 0,
  }))
  await openPane($)
}

// ---------------------------------------------------------------- 3d view in the pane
// bin/crew-3d.mjs renders the web view in a headless Chrome/Edge and streams it as Raster
// cells (each cell the block glyph and two colours that best fit its 4x8 pixels, bin/cells.mjs)
// or, where the terminal draws pictures, as Image frames; each is blitted into the pane's `crew3d`.

const RASTER_KEY = 'crew3d'
const VIEW3D_OFF: View3d = { isOn: false, cols: 0, rows: 0, status: '' }
let view3dGen = 0
let last3d: { cols: number; rows: number; cells: string } | null = null
let lastImage: { path: string; width: number; height: number; gen: number } | null = null
let helper: { port: number; token: string } | null = null
let pointerIn3d = false
let pointerAt = { x: 0.5, y: 0.5 }
let mode3d: 'cells' | 'image' = 'cells'
let isRestarting3d = false

async function getView3d($: EngineInterface): Promise<View3d> {
  return normalize(VIEW3D_OFF, await read($, view3d))
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

/** Standard padded base64, without relying on the host having toBase64 or btoa. */
function base64(bytes: Uint8Array): string {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i] ?? 0
    const b = bytes[i + 1] ?? 0
    const c = bytes[i + 2] ?? 0
    const n = (a << 16) | (b << 8) | c
    out += B64.charAt((n >> 18) & 63) + B64.charAt((n >> 12) & 63)
    out += i + 1 < bytes.length ? B64.charAt((n >> 6) & 63) : '='
    out += i + 2 < bytes.length ? B64.charAt(n & 63) : '='
  }
  return out
}

let blankCache: { key: string; cells: string } | null = null

/** Blank cells for a raster not yet painted: spaces on the terminal's own colours. */
function blankCells(cols: number, rows: number): string {
  const key = `${cols}x${rows}`
  if (blankCache?.key === key) return blankCache.cells
  const words = new Uint32Array(cols * rows * 3)
  for (let i = 0; i < cols * rows; i += 1) {
    words[i * 3] = 0x20
    words[i * 3 + 1] = 0x01000000
    words[i * 3 + 2] = 0x01000000
  }
  blankCache = { key, cells: base64(new Uint8Array(words.buffer)) }
  return blankCache.cells
}

/** Pixels where the terminal draws them (kitty, Ghostty); colour cells everywhere else. */
async function pickMode($: EngineInterface, want: string): Promise<'cells' | 'image'> {
  if (want === 'cells' || want === 'image') return want
  const [term, prog, kitty, ghostty, forced] = await Promise.all([
    $.env.get('TERM'),
    $.env.get('TERM_PROGRAM'),
    $.env.get('KITTY_WINDOW_ID'),
    $.env.get('GHOSTTY_RESOURCES_DIR'),
    $.env.get('CLAUDE_CODE_FORCE_TERMINAL_IMAGES'),
  ])
  // Orca draws kitty Unicode placeholders once its terminal has them; Orca then sets the
  // engine's image flag for the Claude it launches, so the flag is what tells.
  const isOrcaPixels = prog === 'Orca' && Boolean(forced) && forced !== '0'
  const isPixel = /kitty/i.test(term ?? '') || /ghostty|kitty/i.test(prog ?? '') || Boolean(kitty) || Boolean(ghostty) || isOrcaPixels
  return isPixel ? 'image' : 'cells'
}

async function start3d($: EngineInterface, cols: number, rows: number, fps: number, want = 'auto'): Promise<string> {
  const started = await startWeb($, false)
  const w = await getWeb($)
  if (!w.isOn || !w.dir) return started
  mode3d = await pickMode($, want)
  view3dGen += 1
  const gen = view3dGen
  last3d = null
  lastImage = null
  helper = null
  await update($, view3d, () => ({ isOn: true, cols, rows, status: 'starting the renderer…' }))
  void run3d($, gen, cols, rows, fps, w.dir)
  const inOrca = (await $.env.get('TERM_PROGRAM')) === 'Orca'
  const full = inOrca && mode3d === 'cells' ? ' Full size: /crew web opens it in an Orca browser tab.' : ''
  return `Crew 3D view: ${cols}x${rows} cells in the pane, ${mode3d === 'image' ? 'pixels' : 'block glyphs fitted to 4x8 pixels a cell'}, ${fps} fps. Drag to rotate, wheel to zoom, click a crab to pinch it, stroke it to pet it.${full}`
}

async function stop3d($: EngineInterface, status = '') {
  view3dGen += 1
  last3d = null
  lastImage = null
  helper = null
  pointerIn3d = false
  await update($, view3d, () => ({ ...VIEW3D_OFF, status }))
}

async function restart3d($: EngineInterface, cols: number, rows: number, fps: number, want: string) {
  isRestarting3d = false
  if ((await getView3d($)).isOn) await start3d($, cols, rows, fps, want)
}

// ---------------------------------------------------------------- pane scrollbar
// The engine scrolls a pane's body (wheel, arrows, page keys) but draws no scrollbar, and the
// render props carry the window, not the tree's height. A plugin scroll raises `ui.scroll` with
// `contentRows`: the scroll hook keeps it and cancels that move, so measuring moves nothing.
let isMeasuring = false
let paneSig = ''
let paneOffset = 0
/** Where the 3D picture sits in the pane's tree (rows), while it is the first panel. */
let region3d: { top: number; rows: number; cols: number } | null = null

async function measurePane($: EngineInterface) {
  isMeasuring = true
  try {
    await $.ui.scroll({ in: PANE, to: 'start' })
  } catch {
    // A pane not drawn now: measured the next time it is.
  } finally {
    isMeasuring = false
  }
}

/** The pane's pointer events, forwarded to the renderer's page. */
async function sendInput($: EngineInterface, events: unknown[]) {
  if (!helper || events.length === 0) return
  await $.http
    .fetch(`http://127.0.0.1:${helper.port}/input?t=${helper.token}`, { method: 'POST', body: JSON.stringify({ events }) })
    .catch(() => undefined)
}

async function run3d($: EngineInterface, gen: number, cols: number, rows: number, fps: number, dir: string) {
  const page = `file:///${dir.replace(/^\/+/, '')}/index.html`
  const argv = ['node', `${$.plugin.root}/bin/crew-3d.mjs`, '--page', page, '--cols', String(cols), '--rows', String(rows), '--fps', String(fps), '--mode', mode3d]
  if (mode3d === 'image') argv.push('--out', `${dir}/frames`)
  const child = $.process.spawn({ argv })
  let buf = ''
  let denies = 0
  let isDone = false
  try {
    for await (const piece of child) {
      if (gen !== view3dGen) break
      if (piece.stream !== 'stdout') continue
      buf += piece.text
      let at = buf.indexOf('\n')
      while (at >= 0 && !isDone) {
        const line = buf.slice(0, at)
        buf = buf.slice(at + 1)
        at = buf.indexOf('\n')
        if (line.startsWith('P ')) {
          const [, port = '0', token = ''] = line.split(' ')
          helper = { port: Number(port), token }
          continue
        }
        if (line.startsWith('C ') || line.startsWith('I ')) {
          let res: { deny?: string }
          if (line.startsWith('C ')) {
            const [, c = '0', r = '0', cells = ''] = line.split(' ')
            last3d = { cols: Number(c), rows: Number(r), cells }
            res = await $.ui.blit({ requestId: PANE, key: RASTER_KEY, cells, columns: Number(c), rows: Number(r) }).catch(() => ({ deny: 'blit failed' }))
          } else {
            const [, path = '', wd = '0', ht = '0', g = '0'] = line.split(' ')
            lastImage = { path, width: Number(wd), height: Number(ht), gen: Number(g) }
            res = await $.ui
              .blit({ requestId: PANE, key: RASTER_KEY, source: { file: path, format: 'rgb', width: lastImage.width, height: lastImage.height, generation: lastImage.gen } })
              .catch(() => ({ deny: 'blit failed' }))
          }
          if ('deny' in res && res.deny !== undefined) {
            // A terminal the engine draws no pictures in: say why, and go on in cells.
            if (mode3d === 'image' && /draws its alt|cannot read files/.test(res.deny)) {
              await $.ui.toast(`crew 3d: no pixels in this terminal (${res.deny}); using block glyphs`)
              // start3d moves view3dGen on, so this run ends without stopping the new one.
              await start3d($, cols, rows, fps, 'cells')
              return
            }
            denies += 1
            // The pane is closed or the panel hidden for ~5 s: stop the browser.
            if (denies > 40) isDone = true
          } else {
            if (denies > 0 || (await getView3d($)).status) await update($, view3d, v => ({ ...normalize(VIEW3D_OFF, v), status: '' }))
            denies = 0
          }
        } else if (line.startsWith('E ')) {
          await update($, view3d, v => ({ ...normalize(VIEW3D_OFF, v), status: line.slice(2) }))
        }
      }
      if (isDone) break
    }
  } catch (err) {
    if (gen === view3dGen) await update($, view3d, v => ({ ...normalize(VIEW3D_OFF, v), status: `renderer: ${String(err)}` }))
  }
  if (gen === view3dGen) await stop3d($, isDone ? 'stopped: the pane was closed' : (await getView3d($)).status || 'renderer ended')
}

// ---------------------------------------------------------------- hooks

export const register: Register = (on, options) => {
  const cfg = parseConfig(options)
  charRules = cfg.characterRules
  foodFrom = foodFromOf(options.foodFrom)
  const C = PALETTES[cfg.palette]
  // tool.check carries no loop id; the tool.call around it does, keyed by the call's id.
  const callLoop = new Map<string, string | null>()

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'crew',
      description: 'Crew: the live agent dashboard with Clawd crabs and other characters; open, close, reset, layout, the 3D web view, the desktop pet, or your own characters',
      argumentHint: '[open|close|reset|layout auto|compact|wide|mini|web [off|noopen]|3d [off]|pet [off]|characters [reload]|setup]',
    })
    await migrate($)
    cwd = String((e as { cwd?: string }).cwd ?? '')
    // Which task tools this session has decides whether the prompt turns are food (an unreadable list stays unknown and is read again later).
    await update($, setup, () => ({ native: null }))
    await knownSetup($).catch(() => undefined)
    if (cfg.webOnStart) await startWeb($, false).catch(() => undefined)
    // Never awaited: a first start downloads Electron.
    // petOnStart, or the pet was on when this session last ran (a reload, a resume): start it again, which hands the window a new token.
    if (cfg.petOnStart || (await read($, petOn)) === true) void petStart($).catch(() => undefined)
    // A host without usage (headless, an SDK host, a session not yet bound) just starts without it.
    const u = await $.session.usage().catch(() => null)
    if (u) {
      await update($, usage, x => ({
        ...normalize(DEFAULT_USAGE, x),
        pct: u.context.percent ?? null,
        tokens: u.context.tokens ?? null,
        window: u.context.window,
        costUsd: u.cost?.usd ?? null,
        limits: u.rateLimits.map(limitOf),
      }))
    }
    if (cfg.openOnStart) void openPane($).catch(() => undefined)
    await refreshStatus($, cfg)
    return next(e)
  })

  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      await resetAll($)
      await refreshStatus($, cfg)
    }
    return next(e)
  })

  on('command.run', { command: 'crew' }, async ($, e) => {
    const [verb = 'open', arg = '', ...rest] = e.args.trim().split(/\s+/)
    if (verb === '3d') {
      if (arg === 'off') {
        await stop3d($)
        return { text: 'Crew 3D view stopped.' }
      }
      await $.ui.open({ id: PANE, title: TITLE, columns: cfg.view3dColumns, rows: 8 }).catch(() => undefined)
      const cols = Math.max(20, Math.min(240, Number(arg) || cfg.view3dColumns - 2))
      return { text: await start3d($, cols, cfg.view3dRows, cfg.view3dFps, cfg.view3dMode) }
    }
    if (verb === 'setup') return { text: setupReport(await knownSetup($), foodFrom) }
    if (verb === 'characters') return { text: await charactersCommand($, cfg.characters, arg === 'reload') }
    if (verb === 'pet') return { text: arg === 'off' ? await petStop($, rest[0] === 'all') : await petStart($) }
    if (verb === 'web') {
      if (arg === 'off') {
        await update($, web, x => ({ ...normalize(WEB_OFF, x), isOn: false }))
        return { text: 'Crew web view export stopped.' }
      }
      return { text: await startWeb($, arg !== 'noopen') }
    }
    if (verb === 'close') {
      await $.ui.close({ id: PANE })
      return { text: 'Crew closed.' }
    }
    if (verb === 'reset') {
      await resetAll($)
      await refreshStatus($, cfg)
      return { text: 'Crew reset.' }
    }
    if (verb === 'layout') {
      const layout: Layout | null = arg === 'compact' || arg === 'wide' || arg === 'auto' || arg === 'mini' ? arg : null
      if (!layout) return { text: 'Usage: /crew layout auto|compact|wide|mini' }
      await update($, view, v => ({ ...normalize(DEFAULT_VIEW, v), layout }))
      const opened = await openPane($)
      return { text: opened.isPlaced ? `Crew layout: ${layout}.` : `Layout set to ${layout}; the pane is not shown yet: ${opened.reason}` }
    }
    const opened = await openPane($)
    if (!opened.isPlaced) return { text: `Crew is not shown yet: ${opened.reason}` }
    return { text: 'Crew opened. Focus it with ctrl+x tab; 1-6 expand cards, f/s/o open the gate rows. /crew web opens the 3D view.' }
  })

  // A prompt typed while a turn runs waits for its turn: it is a pending item on main's plate (when the prompt turns are food).
  on('prompt.submit', async ($, e, next) => {
    // A letter (a teammate's report, a task notification, another session's message) is told apart by the origin the engine stamped, not by its text.
    // It is registered before the prompt goes on: a letter that opens a turn starts that turn inside next().
    const mid = !e.command && isMailOrigin(e.origin.kind) && e.text.trim() && !isProtocolText(e.text) ? await noteMailIn($, e.text, e.origin.kind, e.turnId).catch(() => undefined) : undefined
    const r = await next(e)
    if (mid !== undefined && r.drop !== undefined) await noteMailDrop($, mid).catch(() => undefined)
    if (r.drop === undefined && e.turnId !== undefined && !e.command && !e.isMeta && USER_ORIGINS.includes(e.origin.kind) && r.text.trim() && (await proxyOn($))) {
      await noteTurnQueued($, r.text)
    }
    return r
  }).catch(($, e, next) => next(e))

  // Who sent a message: a mailbox delivery names its teammate. Observe only; nothing is consumed or rewritten.
  on('session.receive', async ($, e, next) => {
    const from = 'teammate' in e.origin ? e.origin.teammate : ''
    if (!e.agentId && from && !isProtocolText(e.text)) mailFroms = noteMailFrom(mailFroms, e.text, from, await $.clock.now())
    return next(e)
  }).catch(($, e, next) => next(e))

  // A message leaving an agent: main giving a teammate a job, a teammate reporting to the lead. Observe only.
  on('session.send', async ($, e, next) => {
    const sent = await next(e)
    if (sent.isDelivered && !isProtocolText(e.text)) await noteSend($, e.agentId, e.to, e.text).catch(() => undefined)
    return sent
  }).catch(($, e, next) => next(e))

  on('classic.UserPromptSubmit', async ($, e, next) => {
    await noteMode($, e.permission_mode)
    return next(e)
  }).catch(($, e, next) => next(e))

  on('agent.offer', async ($, e, next) => {
    const offered = await next(e)
    if (cfg.architect.test(e.agent) || (cfg.matchDescriptions && cfg.architect.test(e.description))) {
      await update($, roster, r => {
        const x = normalize(DEFAULT_ROSTER, r)
        return x.architectTypes.includes(e.agent) ? x : { architectTypes: [...listOf<string>(x.architectTypes), e.agent].slice(-20) }
      })
    }
    return offered
  }).catch(($, e, next) => next(e))

  on('turn.start', async ($, e, next) => {
    // The turn a pet question started: its text holds the user's words (the engine may frame them), so a match by containment.
    let askKey = ''
    if (!e.agentId && e.text) {
      const at = askWaits.findIndex(w => e.text.includes(w.key))
      if (at >= 0) {
        askKey = askWaits[at]?.key ?? ''
        askWaits.splice(at, 1)
        askTurns.add(e.turnId)
      }
    }
    if (!e.agentId) {
      const isLetter = await noteMailStart($, e.turnId, e.text ?? '').catch(() => false)
      if (!isLetter && (await proxyOn($))) await noteTurnStart($, e.turnId, e.text ?? '', askKey).catch(() => undefined)
    }
    const [now, cost] = await Promise.all([$.clock.now(), costNow($)])
    await update($, turn, () => ({ ...DEFAULT_TURN, startedAt: now, costAtStart: cost }))
    await update($, main, m => ({ ...normalize(DEFAULT_MAIN, m), isRunning: true }))
    await act($, 'main', 'think', '', '')
    if (e.text) await emit($, { kind: 'prompt', from: 'main', text: shorten(redact(promptLine(e.text).text), 60) })
    // The first prompt of the session names it on the desktop pet's nameplate.
    if (e.text && promptLine(e.text).who === 'you' && !(await read($, sessionTitle))) await update($, sessionTitle, () => titleOf(e.text ?? ''))
    // A background architect's report reaches the main loop as the text opening this turn. The
    // SubagentHandback tool call (in tool.call) normally carries it first; this is the fallback.
    const back = e.text ? handbackOf(e.text) : null
    const a = back ? await getArchitect($) : null
    if (back && a && a.ids.includes(back.from)) {
      const advice = adviceLine(back.body)
      if (advice && advice !== a.lastAdvice) await noteAdvice($, cfg, advice)
    } else if (e.text) {
      const p = promptLine(e.text)
      await say($, p.who, p.text)
    }
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    // The main loop's model is known when its request starts; a long first request shouldn't read "—".
    if (!e.agentId) {
      await update($, main, m => {
        const x = normalize(DEFAULT_MAIN, m)
        return { ...x, model: e.model, effort: String(e.effort ?? x.effort), steps: x.steps + 1 }
      })
      // Time the response as it passes: the first piece that is not the engine's envelope, then the
      // stop chunk. Two clock reads in the stream and nothing stored until it has ended.
      const sentAt = await $.clock.now()
      let firstAt: number | null = null
      let stopAt: number | null = null
      const s = next(e)
      for await (const c of s) {
        if (c.kind === 'stop') stopAt = await $.clock.now()
        else if (firstAt === null && c.kind !== 'engine') firstAt = await $.clock.now()
        yield c
      }
      const result = await s.result
      const speed = result.usage && stopAt !== null ? stepSpeed(sentAt, firstAt, stopAt, result.usage.output_tokens) : null
      if (speed) await update($, main, m => ({ ...normalize(DEFAULT_MAIN, m), speed }))
      return result
    }
    const result = yield* next(e)
    const id = e.agentId
    const [cards, a] = await Promise.all([getCards($), getArchitect($)])
    if (cards.some(c => c.id === id)) {
      const step = { model: e.model, usage: result.usage, stopReason: result.stopReason }
      await update($, agents, list => listOf<unknown>(list).map(normalizeCard).map(c => (c.id === id ? applyStep(c, step) : c)))
      if (result.stopReason === 'max_tokens') await say($, await whoIs($, id), 'hit max_tokens', 'error', id)
    } else if (!a.ids.includes(id)) {
      const now = await $.clock.now()
      await update($, loops, l => stepLoop(listOf<Loop>(l), id, now))
    }
    return result
  })

  on('session.measure', async ($, e, next) => {
    await update($, usage, x => ({
      ...normalize(DEFAULT_USAGE, x),
      pct: e.context.percent ?? null,
      tokens: e.context.tokens ?? null,
      window: e.context.window,
      costUsd: e.cost?.usd ?? null,
      limits: e.rateLimits.map(limitOf),
    }))
    if (e.changed.includes('context')) await refreshStatus($, cfg)
    return next(e)
  })

  on('session.compact', async ($, e, next) => {
    const done = await next(e)
    if (!e.agentId && e.trigger !== 'precompute') {
      const now = await $.clock.now()
      await update($, usage, x => {
        const u = normalize(DEFAULT_USAGE, x)
        return { ...u, compactions: u.compactions + 1, lastCompactAt: now }
      })
      await say($, 'main', `context compacted (${e.trigger})`)
      await emit($, { kind: 'compact', from: 'main', text: `compacted (${e.trigger})` })
    }
    return done
  }).catch(($, e, next) => next(e))

  on('tool.check', async ($, e, next) => {
    const verdict = await next(e)
    if (e.tool_use_id) {
      const check: Check = {
        id: e.tool_use_id,
        tool: e.tool,
        bucket: bucketOf(e.tool),
        verdict: verdict.decision === 'allow' ? 'rule' : verdict.decision,
        inSubagent: Boolean(callLoop.get(e.tool_use_id)),
        detail: shorten(describeInput(e.tool, e.input), 90),
        at: await $.clock.now(),
      }
      await update($, gate, g => recordCheck(normalizeGate(g), check))
      if (check.verdict === 'ask') await emit($, { kind: 'check', from: callLoop.get(e.tool_use_id) ?? 'main', tool: e.tool, text: check.detail })
      // The status line updates when the call settles; only a refusal ends here.
      if (verdict.decision === 'deny') {
        await say($, 'gate', `denied by rule · ${check.detail}`, 'error')
        await emit($, { kind: 'deny', from: callLoop.get(e.tool_use_id) ?? 'main', tool: e.tool, text: check.detail })
        await refreshStatus($, cfg)
      }
    }
    return verdict
  }).catch(($, e, next) => next(e))

  on('tool.call', async ($, e, next) => {
    callLoop.set(e.tool_use_id, e.agentId ?? null)
    const key = e.agentId ?? 'main'
    const touch = describeCall(String(e.tool), e as unknown as Record<string, unknown>, cwd)
    if (String(e.tool) !== 'SubagentHandback') {
      await act($, key, touch.verb, String(e.tool), touch.target)
      if (touch.file && touch.op) {
        const path = shortPath(touch.file, cwd)
        const op = touch.op
        const abs = absPath(touch.file, cwd)
        const now = await $.clock.now()
        await update($, files, list => touchFile(listOf<FileNode>(list), path, key, op, now, abs))
        await emit($, { kind: op === 'r' ? 'read' : 'write', from: key, to: path, tool: String(e.tool), text: path })
      } else if (e.tool !== 'Agent') {
        await emit($, { kind: 'tool', from: key, tool: String(e.tool), text: `${e.tool} ${touch.target}`.trim() })
      }
    }
    if (e.tool === 'Agent' && !(await read($, autoOpened))) {
      // Open on the session's first subagent only; after a close it stays closed (/crew reopens).
      await update($, autoOpened, () => true)
      void openPane($).catch(() => undefined)
    }
    const ran = await next(e).finally(() => callLoop.delete(e.tool_use_id))
    const didRun = ran.deny === undefined
    if (didRun && ran.isError !== true && TASK_TOOLS.has(String(e.tool))) {
      await noteTasks($, e as unknown as Record<string, unknown>, ran as unknown as { result?: unknown; text?: unknown }, key).catch(() => undefined)
      await noteNativeSeen($).catch(() => undefined)
    }
    // Settle this call's pending ask, if it had one; skip the write (and the redraw) otherwise.
    const g0 = await getGate($)
    const isSettled = settleCheck(g0, e.tool_use_id, didRun) !== g0
    if (isSettled) await update($, gate, g => settleCheck(normalizeGate(g), e.tool_use_id, didRun))
    // A background agent hands its report back through this tool; an architect's report is its advice.
    if (String(e.tool) === 'SubagentHandback') {
      const message = (e as unknown as { message?: unknown }).message
      const a = e.agentId ? await getArchitect($) : null
      if (a && e.agentId && a.ids.includes(e.agentId) && typeof message === 'string') {
        const advice = adviceLine(message)
        if (advice && advice !== a.lastAdvice) await noteAdvice($, cfg, advice)
      }
      return ran
    }
    if (e.tool === 'Agent') {
      if (isSettled) await refreshStatus($, cfg)
      return ran
    }
    const hasFailed = didRun && ran.isError === true
    if (hasFailed || !didRun) {
      await act($, key, 'failed', String(e.tool), touch.target)
      await emit($, { kind: didRun ? 'fail' : 'deny', from: key, tool: String(e.tool), text: `${e.tool} ${touch.target}`.trim() })
    }
    const isEdit = !hasFailed && didRun && EDIT_TOOLS.has(e.tool)
    const t0 = await getTurn($)
    if (isEdit || hasFailed || (!e.agentId && t0.errorStreak > 0)) {
      await update($, turn, t => afterCall(normalize(DEFAULT_TURN, t), { inSubagent: Boolean(e.agentId), hasFailed, isEdit }))
    }
    const text = shorten(describeInput(e.tool, e), 64)
    if (e.agentId) {
      const id = e.agentId
      await update($, agents, list =>
        listOf<unknown>(list)
          .map(normalizeCard)
          .map(c => (c.id === id ? noteTool(c, { tool: e.tool, text, isError: hasFailed || ran.deny !== undefined }) : c)),
      )
    }
    // The log keeps what is worth a glance: refusals, errors and edits; the rest is on the cards.
    if (ran.deny !== undefined) await say($, await whoIs($, e.agentId), `${text}  denied`, 'error', e.agentId ?? null)
    else if (hasFailed) await say($, await whoIs($, e.agentId), `${text}  ✗`, 'error', e.agentId ?? null)
    else if (isEdit) await say($, await whoIs($, e.agentId), text, 'info', e.agentId ?? null)
    if (isSettled || !didRun) await refreshStatus($, cfg)
    return ran
  }).catch(($, e, next) => next(e))

  // A server-side review tool never reaches tool.call: it shows only in the assistant's rows.
  on('session.append', async ($, e, next) => {
    if (!e.agentId && e.message.type === 'assistant') {
      const a = await getArchitect($)
      // Consults this row opened: their result may be in the same row, after the stale read above.
      const opened = new Set<string>()
      for (const block of e.message.content as unknown as readonly ServerBlock[]) {
        if (block.type === 'server_tool_use' && block.name && block.id && cfg.architect.test(block.name)) {
          if (a.seen.includes(block.id)) continue
          const id = block.id
          await update($, architect, x => {
            const y = normalize(DEFAULT_ARCHITECT, x)
            return { ...y, seen: [...listOf<string>(y.seen), id].slice(-60) }
          })
          opened.add(id)
          await consultStarted($, cfg, id, `${block.name} tool`)
        } else if (block.type.endsWith('_tool_result') && block.tool_use_id) {
          const id = block.tool_use_id
          const isOpen = opened.has(id) || (await getArchitect($)).consults.some(c => c.id === id && c.endAt === null)
          if (isOpen) await consultEnded($, cfg, null, id)
        }
      }
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    if (!e.parentAgentId) await noteMode($, e.permissionMode)
    if (started.deny !== undefined || !started.agentId) return started
    const id = started.agentId
    const parent = e.parentAgentId ?? 'main'
    await update($, parents, p => ({ ...p, [id]: parent }))
    await act($, id, 'think', '', '')
    await emit($, { kind: 'spawn', from: parent, to: id, text: shorten(`${e.subagentType}: ${e.description}`, 60) })
    if (await isArchitectType($, cfg, e.subagentType)) {
      await update($, architect, a => {
        const x = normalize(DEFAULT_ARCHITECT, a)
        return { ...x, ids: [...listOf<string>(x.ids), id].slice(-40) }
      })
      await update($, loops, l => listOf<Loop>(l).filter(x => x.id !== id))
      await consultStarted($, cfg, id, e.subagentType.split(':').pop() ?? 'agent')
      await emit($, { kind: 'consult', from: parent, to: id, text: e.subagentType })
      return started
    }
    const card: AgentCard = {
      ...normalizeCard({}),
      id,
      type: e.name ?? e.subagentType,
      model: started.model,
      description: e.description,
      spawnedAt: await $.clock.now(),
      ...(e.isTeammate ? { isTeammate: true } : {}),
    }
    await update($, agents, list => [...listOf<unknown>(list).map(normalizeCard), card].slice(-24))
    // A teammate's spawn is its first job (it is handed back to whoever spawned it when the teammate reports).
    if (e.isTeammate) {
      const now = await $.clock.now()
      await update($, tasks, b => applyAssign(normalizeBook(b), id, assignTitle(e.description, e.prompt), parent, now))
      await queueWeb($)
    }
    await update($, loops, l => listOf<Loop>(l).filter(x => x.id !== id))
    await say($, shorten(cardTitle(card), 12), `spawned · ${card.type}`, 'info', id)
    await refreshStatus($, cfg)
    return started
  }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    const id = e.agentId
    const now = await $.clock.now()
    if (!id) {
      const [t, cards, cost] = await Promise.all([getTurn($), getCards($), costNow($)])
      const r = receiptOf(t, {
        durationMs: e.durationMs,
        agentsSince: cards.filter(c => c.spawnedAt >= t.startedAt).length,
        costNow: cost,
        reason: e.reason,
      })
      await update($, receipt, () => r)
      // Only the turn that came from a pet question gives the pet something to say.
      if (askTurns.delete(e.turnId)) await update($, lastReply, () => replyOf(e.answer, e.reason, now))
      await update($, main, m => ({ ...normalize(DEFAULT_MAIN, m), isRunning: false }))
      await act($, 'main', e.reason === 'answer' ? 'done' : 'failed', '', '')
      await noteTurnEnd($, e.turnId, e.reason).catch(() => undefined)
      await noteMailEnd($, e.turnId, e.reason).catch(() => undefined)
      await refreshStatus($, cfg)
      await queueWeb($)
      return done
    }
    if ((await getArchitect($)).ids.includes(id)) {
      await consultEnded($, cfg, e.answer, id)
      await emit($, { kind: 'answer', from: id, to: (await getParents($))[id] ?? 'main', text: shorten(e.answer, 60) })
      return done
    }
    const cards = await getCards($)
    if (cards.some(c => c.id === id)) {
      const status = e.reason === 'answer' ? 'done' : e.reason === 'aborted' ? 'stopped' : 'failed'
      await update($, agents, list =>
        listOf<unknown>(list)
          .map(normalizeCard)
          .map(c => (c.id === id ? { ...c, status, endedAt: now, answer: shorten(e.answer, 400) } : c)),
      )
      // A finished subagent hands its ticket to the parent, who eats it (the counter the pet shows). A teammate goes idle after every message,
      // so its end is no delivery: what it was given is closed here instead, and counted when it is.
      if ((await settleTeammates($)).find(c => c.id === id)?.isTeammate) {
        await update($, tasks, b => applyAssignDone(normalizeBook(b), id, true, now, e.reason))
      } else if (status === 'done') {
        const eater = (await getParents($))[id] ?? 'main'
        await update($, tasks, b => bumpEaten(normalizeBook(b), eater))
      }
      const card = cards.find(c => c.id === id)
      const took = card ? fmtDuration(now - card.spawnedAt) : ''
      await say($, await whoIs($, id), status === 'done' ? `done · ${took}` : status, status === 'done' ? 'done' : 'error', id)
      await act($, id, status === 'done' ? 'done' : 'failed', '', '')
      await emit($, { kind: status === 'done' ? 'answer' : 'fail', from: id, to: (await getParents($))[id] ?? 'main', text: status === 'done' ? shorten(e.answer, 60) : status })
    } else {
      await update($, loops, l => listOf<Loop>(l).map(x => (x.id === id ? { ...x, isDone: true, lastAt: now } : x)))
    }
    await refreshStatus($, cfg)
    return done
  })

  // The 3D view's input layer posts here; the pointer goes on to the renderer's page.
  on('ui.message', async ($, e, next) => {
    if (e.requestId !== PANE || e.element !== 'input3d') return next(e)
    const data = e.data as { type?: string; inside?: boolean; x?: number; y?: number; events?: unknown[] }
    if (data?.type === 'hover') pointerIn3d = data.inside === true
    else if (data?.type === 'at' && typeof data.x === 'number' && typeof data.y === 'number') pointerAt = { x: data.x, y: data.y }
    else if (data?.type === 'input' && Array.isArray(data.events)) await sendInput($, data.events.slice(0, 200))
    return {}
  }).catch(($, e, next) => next(e))

  // Every move tells the tree's height (for the scrollbar); the wheel over the 3D picture zooms
  // it instead of scrolling the pane.
  on('ui.scroll', { requestId: PANE }, async ($, e, next) => {
    if (typeof e.contentRows === 'number' && e.contentRows !== (await read($, paneRows))) await update($, paneRows, () => e.contentRows)
    if (isMeasuring && e.origin.kind !== 'person') return {}
    const r3 = region3d
    const at = e.pointer ? paneOffset + e.pointer.row : -1
    const isOver3d = r3 && e.pointer ? at >= r3.top && at < r3.top + r3.rows && e.pointer.column < r3.cols : pointerIn3d
    if (!isOver3d || !helper || e.by === 0 || e.origin.kind !== 'person') return next(e)
    await sendInput($, [{ kind: 'wheel', x: pointerAt.x, y: pointerAt.y, dy: Math.max(-10, Math.min(10, e.by)) }])
    return {}
  }).catch(($, e, next) => next(e))

  // ---------------------------------------------------------------- drawing

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const els = $.ui.resolve(e)
    const { Box, Text, Button } = els
    const hasClient = 'Client' in els
    const [m, u, a, g, allCards, lp, allLines, t, r, v, now] = await Promise.all([
      getMain($),
      getUsage($),
      getArchitect($),
      getGate($),
      getCards($),
      getLoops($),
      getLog($),
      getTurn($),
      read($, receipt),
      getView($),
      $.clock.now(),
    ])
    const [allActs, allFiles, allParents, v3, pf, dis] = await Promise.all([getActs($), getFiles($), getParents($), getView3d($), read($, petFocus), getDismissed($)])
    // Dismissed agents (and the file links only they made) are not drawn; they come back when they work again.
    const hiddenNow = hiddenIds(allCards, dis, allActs)
    const { cards, acts: ac, files: fl, parents: pa } = withoutHidden({ cards: allCards, files: allFiles, acts: allActs, events: [], parents: allParents }, hiddenNow)
    const lines = allLines.filter(l => !l.agentId || !hiddenNow.has(l.agentId))
    // Docked, the last column is the scrollbar's.
    const isDock = e.props.placement === 'dock'
    const W = Math.max(40, e.props.bodyColumns - (isDock ? 1 : 0))
    const layout = v.layout ?? cfg.layout
    const isWide = layout === 'wide' || (layout === 'auto' && W >= 110)
    const colW = isWide ? Math.floor((W - 2) / 2) : W
    const modelName = prettyModel(m.model)
    const viewed = e.props.view?.agentId ?? null
    const advising = isAdvising(a)
    const running = cards.filter(c => c.status === 'running')
    const showArchitect = a.consults.length > 0 || a.ids.length > 0
    const motion = cfg.motion && hasClient
    // A panel with nothing to show yet takes no room: most sessions never spawn an agent.
    const isEmpty: Record<Panel, boolean> = {
      main: false,
      architect: !showArchitect,
      gate: g.recent.length === 0 && gateSummary(g).total === 0,
      agents: cards.length === 0,
      loops: lp.length === 0,
      receipt: !m.isRunning && !r,
      crew: false,
      '3d': !v3.isOn && !v3.status,
      log: false,
    }
    const panels = cfg.panels.filter(p => !isEmpty[p])
    const decider = m.mode === 'auto' ? 'classifier' : 'you'

    // A connector between panels: animated while its flow is live, a dim line otherwise.
    const rail = (key: string, active: boolean, color: string, width: number, marks: number[] = [], isMerge = false) =>
      motion ? (
        <els.Client
          key={key}
          module="./rail.tsx"
          width={width}
          height={1}
          props={{ active, width, color, dim: C.faint, marks, isMerge }}
        />
      ) : (
        <Text color={C.faint}>{'─'.repeat(Math.max(1, width))}</Text>
      )

    // A start time of 0 is unknown (state saved before it was recorded): no clock, not decades.
    const clock = (key: string, since: number, endAt: number | null, color: string) =>
      since <= 0 ? (
        <Text color={color}>—</Text>
      ) : hasClient ? (
        <els.Client key={key} module="./elapsed.tsx" props={{ since, now, endAt, color }} />
      ) : (
        <Text color={color}>{fmtTimer((endAt ?? now) - since)}</Text>
      )

    // ---- main
    const effortN = { low: 1, medium: 2, high: 3, xhigh: 4, max: 4 }[m.effort] ?? 0
    const ctxGauge = u.pct !== null ? gauge(u.pct, 10) : null
    const mainPanel = (w: number) => (
      <Box flexDirection="column" borderStyle="round" borderColor={C.main} paddingX={1} width={w}>
        <Box justifyContent="space-between">
          <Text color={C.main} bold>
            {modelName} · main
          </Text>
          <Text color={m.isRunning ? C.main : C.dim}>{m.isRunning ? '● working' : '○ idle'}</Text>
        </Box>
        <Text wrap="truncate">
          <Text dimColor>effort </Text>
          <Text color={C.main}>{'▮'.repeat(effortN) + '▯'.repeat(4 - effortN)} </Text>
          <Text color={C.main} bold>
            {m.effort || '—'}
          </Text>
          {m.mode ? <Text dimColor>{`   mode ${m.mode}`}</Text> : null}
          <Text dimColor>{`   ${m.steps} req`}</Text>
        </Text>
        {ctxGauge ? (
          <Text wrap="truncate">
            <Text dimColor>ctx </Text>
            <Text color={u.pct !== null && u.pct >= 80 ? C.warn : C.main}>{ctxGauge.on}</Text>
            <Text color={C.faint}>{ctxGauge.off}</Text>
            <Text bold>{` ${Math.round(u.pct ?? 0)}%`}</Text>
            {u.tokens !== null ? <Text dimColor>{` ${kTokens(u.tokens)}/${kTokens(u.window)}`}</Text> : null}
            {u.compactions > 0 ? <Text color={C.amber}>{`  ⟲${u.compactions}`}</Text> : null}
          </Text>
        ) : null}
        {u.costUsd !== null || u.limits.length > 0 ? (
          <Text wrap="truncate">
            {u.costUsd !== null ? <Text color={C.text}>{`${fmtUsd(u.costUsd)}   `}</Text> : null}
            {u.limits.slice(0, 2).map(l => {
              const lg = gauge(l.pct, 5)
              // The time to each reset where the line has room for it: both windows fit from 56 columns,
              // so a wide pane's half column (59 at 120) has them and a 40-column pane keeps its gauges.
              const resetIn = w >= 56 ? fmtResetIn(l.resetsAt, now) : ''
              return (
                <Text wrap="truncate">
                  <Text dimColor>{`${limitLabel(l.kind)} `}</Text>
                  <Text color={l.pct >= 80 ? C.warn : C.main}>{lg.on}</Text>
                  <Text color={C.faint}>{lg.off}</Text>
                  <Text dimColor>{` ${Math.round(l.pct)}%${resetIn ? ` ↻${resetIn}` : ''}  `}</Text>
                </Text>
              )
            })}
          </Text>
        ) : null}
        {m.speed ? <Text dimColor wrap="truncate">{`last req  ${fmtSpeed(m.speed)}`}</Text> : null}
      </Box>
    )

    // ---- architect
    const lastConsult = a.consults[a.consults.length - 1]
    const architectPanel = (w: number) => {
      const tl = consultTimeline(a, now, Math.max(8, w - 4))
      return (
        <Box flexDirection="column" borderStyle="round" borderColor={C.arch} paddingX={1} width={w}>
          <Box justifyContent="space-between">
            <Text color={C.arch} bold>
              {cfg.architectLabel} · {advising ? 'advising' : 'on call'}
            </Text>
            <Text>
              <Text dimColor>consults </Text>
              <Text color={C.arch} bold>
                {a.consults.length}
              </Text>
            </Text>
          </Box>
          <Text color={C.arch}>{tl}</Text>
          {lastConsult ? (
            <Text dimColor wrap="truncate">
              {advising
                ? `consulting since ${fmtClock(lastConsult.at)}`
                : `last ${fmtDuration(now - (lastConsult.endAt ?? lastConsult.at))} ago · took ${fmtDuration((lastConsult.endAt ?? now) - lastConsult.at)}`}
            </Text>
          ) : (
            <Text dimColor>not consulted yet</Text>
          )}
          {cfg.moments ? (
            <Box flexWrap="wrap" columnGap={2}>
              {(['before a plan', 'error repeats', 'before done'] as const).map(mo => {
                const isOn = lastConsult?.moment === mo
                return (
                  <Text color={isOn ? C.arch : C.dim} bold={isOn}>
                    {isOn ? '◆' : '◇'} {mo}
                  </Text>
                )
              })}
              <Text color={C.faint}>(inferred)</Text>
            </Box>
          ) : null}
          {a.lastAdvice ? (
            <Text color={C.arch} wrap="truncate">
              » {a.lastAdvice}
            </Text>
          ) : null}
        </Box>
      )
    }

    // ---- gate
    const s = gateSummary(g)
    const verdictColor = (c: Check) =>
      c.verdict === 'rule' ? C.gate : c.verdict === 'cleared' ? C.cleared : c.verdict === 'ask' ? C.amber : C.warn
    const gatePanel = (w: number) => {
      const strip = g.recent.slice(-Math.max(8, w - 4))
      const open = v.gateOpen
      return (
        <Box flexDirection="column" borderStyle="round" borderColor={C.gate} paddingX={1} width={w}>
          <Box justifyContent="space-between">
            <Text color={C.gate} bold>
              {cfg.gateLabel} · permissions
            </Text>
            <Text dimColor>{`${s.total} checks`}</Text>
          </Box>
          <Box>
            {strip.length === 0 ? <Text color={C.faint}>no checks yet</Text> : null}
            {strip.map(c => (
              <Text color={verdictColor(c)} dimColor={c.inSubagent}>
                {c.verdict === 'deny' ? '✗' : '■'}
              </Text>
            ))}
          </Box>
          <Text wrap="truncate">
            <Text color={C.gate}>■</Text>
            <Text dimColor>{` ${s.rule} allowed  `}</Text>
            <Text color={C.cleared}>■</Text>
            <Text dimColor>{` ${s.cleared} ${decider}  `}</Text>
            {s.ask > 0 ? <Text color={C.amber}>{`■ ${s.ask} pending  `}</Text> : null}
            <Text color={s.deny > 0 ? C.warn : C.dim}>{`✗ ${s.deny} denied`}</Text>
            {w >= 80 && g.recent.some(c => c.inSubagent) ? <Text color={C.faint}>{'  dim: in subagents'}</Text> : null}
          </Text>
          <Box columnGap={2}>
            {(['file', 'shell', 'other'] as const).map((b: Bucket) => {
              const tl = g.totals[b]
              const n = tl.rule + tl.ask + tl.cleared + tl.deny
              return (
                <Button
                  key={`gate-${b}`}
                  plain
                  hotkey={b[0]}
                  label={`${b} ${n}${open === b ? ' ▾' : ''}`}
                  dimColor={n === 0}
                  onPress={() => update($, view, x => ({ ...normalize(DEFAULT_VIEW, x), gateOpen: normalize(DEFAULT_VIEW, x).gateOpen === b ? null : b }))}
                />
              )
            })}
          </Box>
          {open
            ? g.recent
                .filter(c => c.bucket === open)
                .slice(-5)
                .map(c => (
                  <Text wrap="truncate">
                    <Text color={verdictColor(c)}>{c.verdict === 'deny' ? '✗ ' : '■ '}</Text>
                    <Text color={C.dim}>{`${(c.verdict === 'rule' ? 'allowed' : c.verdict === 'cleared' ? decider : c.verdict === 'ask' ? 'pending' : 'denied').padEnd(10)} `}</Text>
                    <Text dimColor={c.inSubagent}>{shorten(c.detail, Math.max(10, w - 18))}</Text>
                  </Text>
                ))
            : null}
        </Box>
      )
    }

    // ---- agents: cards up to the limit, swimlanes beyond it
    const statusColor = (c: AgentCard) => (c.status === 'failed' ? C.warn : c.status === 'done' ? C.gate : C.agent)
    const glyph = (c: AgentCard) => (c.status === 'running' ? '◐' : c.status === 'done' ? '✓' : c.status === 'failed' ? '✗' : '■')
    const expandOnPress = (id: string) => () =>
      update($, view, x => ({ ...normalize(DEFAULT_VIEW, x), expanded: normalize(DEFAULT_VIEW, x).expanded === id ? null : id }))

    const agentsPanel = (w: number) => {
      // Cards need 20 columns each; when the pane can't hold the limit, lanes take over.
      const fit = Math.max(1, Math.min(cfg.maxCards, Math.floor((w + 1) / 21)))
      const useLanes = cards.length > fit
      const header = (
        <Box justifyContent="space-between" width={w}>
          <Text bold>{`agents · ${running.length} running · ${cards.length} total`}</Text>
          {cards.length > 0 ? <Text color={C.faint}>1-{Math.min(cards.length, useLanes ? 6 : fit)} expand</Text> : null}
        </Box>
      )
      if (cards.length === 0) {
        return (
          <Box flexDirection="column" width={w}>
            {header}
            <Text color={C.faint}>no subagents yet</Text>
          </Box>
        )
      }
      if (useLanes) {
        const shown = cards.slice(-6)
        const barW = Math.max(8, w - 28)
        const geo = lanes(shown, now, barW)
        return (
          <Box flexDirection="column" width={w}>
            {header}
            {cards.length > shown.length ? <Text color={C.faint}>{`+${cards.length - shown.length} earlier`}</Text> : null}
            {shown.map((c, i) => {
              const gm = geo[i]
              const isViewed = viewed === c.id
              return (
                <Box>
                  <Text color={statusColor(c)} bold={isViewed}>{`${isViewed ? '▶' : glyph(c)} `}</Text>
                  <Box width={17}>
                    <Button key={`card-${c.id}`} plain hotkey={String(i + 1)} label={shorten(cardTitle(c), 14)} onPress={expandOnPress(c.id)} />
                  </Box>
                  <Text color={C.faint}>{' ' + '·'.repeat(gm?.before ?? 0)}</Text>
                  <Text color={statusColor(c)}>{'━'.repeat(gm?.bar ?? 1)}</Text>
                  <Text color={C.faint}>{'·'.repeat(gm?.after ?? 0) + ' '}</Text>
                  {clock(`lane-clock-${c.id}`, c.spawnedAt, c.endedAt, C.dim)}
                </Box>
              )
            })}
          </Box>
        )
      }
      const shown = cards.slice(-fit)
      const cardW = Math.max(20, Math.floor((w - (shown.length - 1)) / shown.length))
      const centers = shown.map((_, i) => i * (cardW + 1) + Math.floor(cardW / 2))
      return (
        <Box flexDirection="column" width={w}>
          {header}
          {rail('fan-out', running.length > 0, C.agent, w, centers)}
          <Box columnGap={1}>
            {shown.map((c, i) => {
              const isViewed = viewed === c.id
              const sameModel = !c.model || prettyModel(c.model) === modelName
              return (
                <Box
                  flexDirection="column"
                  borderStyle={isViewed ? 'double' : 'round'}
                  borderColor={c.lastStop === 'max_tokens' ? C.warn : C.agent}
                  borderDimColor={c.status !== 'running' && !isViewed}
                  width={cardW}
                  paddingX={1}
                >
                  <Button key={`card-${c.id}`} plain hotkey={String(i + 1)} label={titleLines(cardTitle(c), cardW - 7, cardW - 4)[0]} onPress={expandOnPress(c.id)} />
                  <Text bold wrap="truncate">
                    {titleLines(cardTitle(c), cardW - 7, cardW - 4)[1]}
                  </Text>
                  <Text color={C.dim} wrap="truncate">
                    {sameModel ? c.type : `${c.type} · ${prettyModel(c.model)}`}
                  </Text>
                  <Text dimColor wrap="truncate">
                    {c.steps > 0 ? `ctx ${kTokens(c.ctx)} · out ${kTokens(c.out)} · ${c.steps} st` : 'starting…'}
                  </Text>
                  <Box>
                    <Text color={c.lastStop === 'max_tokens' ? C.warn : statusColor(c)}>
                      {cardW >= 26 ? `${glyph(c)} ${c.lastStop === 'max_tokens' ? 'max_tokens' : c.status} ` : `${glyph(c)} `}
                    </Text>
                    <Box flexShrink={0}>{clock(`card-clock-${c.id}`, c.spawnedAt, c.endedAt, C.dim)}</Box>
                  </Box>
                </Box>
              )
            })}
          </Box>
          {rail('merge', running.length > 0, C.agent, w, centers, true)}
        </Box>
      )
    }

    const expandedCard = cards.find(c => c.id === v.expanded)
    const expandedPanel = (w: number) =>
      expandedCard ? (
        <Box flexDirection="column" borderStyle="single" borderColor={C.agent} paddingX={1} width={w}>
          <Text bold wrap="wrap">
            {expandedCard.description || expandedCard.type}
          </Text>
          <Text dimColor wrap="truncate">{`${expandedCard.type} · ${prettyModel(expandedCard.model)} · ${expandedCard.status} · ${expandedCard.steps} steps`}</Text>
          {expandedCard.tools.length === 0 ? <Text color={C.faint}>no tool calls yet</Text> : null}
          {expandedCard.tools.map(n => (
            <Text color={n.isError ? C.warn : C.text} wrap="truncate">
              {`${n.isError ? '✗' : '·'} ${n.text}`}
            </Text>
          ))}
          {expandedCard.answer ? (
            <Text dimColor wrap="wrap">
              {`» ${shorten(expandedCard.answer, 240)}`}
            </Text>
          ) : null}
        </Box>
      ) : null

    // ---- the file the desktop pet asked to show: its path, who touched it, a summary or its first lines
    const focusRows = pf ? 3 + (pf.summary ? 3 : Math.min(pf.head.length, 12)) : 0
    const focusPanel = (w: number) => {
      if (!pf) return null
      const node = fl.find(n => n.abs === pf.abs)
      const who = node
        ? Object.entries(node.by)
            .map(([k, op]) => `${k === 'main' ? 'main' : (cards.find(c => c.id === k)?.type ?? k)} ${op === 'r' ? 'read' : op === 'w' ? 'wrote' : 'read+wrote'}`)
            .join(' · ')
        : ''
      const s = pf.summary
      return (
        <Box flexDirection="column" borderStyle="round" borderColor={C.main} paddingX={1} width={w}>
          <Box justifyContent="space-between" width={w - 4}>
            <Text bold wrap="truncate">
              {`focus · ${pf.path}`}
            </Text>
            <Button key="focus-close" plain label="✕ close" onPress={() => update($, petFocus, () => null)} />
          </Box>
          {who ? (
            <Text dimColor wrap="truncate">
              {who}
            </Text>
          ) : null}
          {s?.title ? <Text bold wrap="truncate">{s.title}</Text> : null}
          {s?.lead ? <Text wrap="wrap">{s.lead}</Text> : null}
          {s && s.heads.length > 0 ? (
            <Text dimColor wrap="truncate">
              {s.heads.map(h => `# ${h}`).join('  ')}
            </Text>
          ) : null}
          {s && s.decls.length > 0 ? (
            <Text dimColor wrap="truncate">
              {s.decls.join(' · ')}
            </Text>
          ) : null}
          {!s
            ? pf.head.map(l => (
                <Text dimColor wrap="truncate">
                  {l}
                </Text>
              ))
            : null}
        </Box>
      )
    }

    // ---- other loops (workflow agents, forks): ids that match no card
    const loopsPanel = (w: number) => {
      if (lp.length === 0) return null
      const active = lp.filter(l => isLoopActive(l, now)).length
      const dots = lp.slice(-Math.max(4, w - 38))
      return (
        <Box width={w}>
          <Text bold>other loops </Text>
          <Text dimColor>{`${lp.length} seen · ${active} active  `}</Text>
          {dots.map(l => (
            <Text color={isLoopActive(l, now) ? C.agent : l.isDone ? C.dim : C.faint}>{isLoopActive(l, now) ? '●' : l.isDone ? '✓' : '○'}</Text>
          ))}
        </Box>
      )
    }

    // ---- receipt: the turn now, or the last one
    const receiptPanel = (w: number) => {
      const isReview = t.isReviewing
      return (
        <Box flexDirection="column" borderStyle="round" borderColor={C.main} borderDimColor={!m.isRunning && !isReview} paddingX={1} width={w}>
          {m.isRunning ? (
            <Box>
              <Text color={C.main} wrap="truncate">{`◐ back to ${modelName.toLowerCase()} · turn `}</Text>
              <Box flexShrink={0}>{clock('turn-clock', t.startedAt, null, C.main)}</Box>
              {w >= 60 ? <Text dimColor wrap="truncate">{` · ${plural(t.edits, 'edit')} · ${plural(t.errors, 'error')}`}</Text> : null}
            </Box>
          ) : r ? (
            <Text wrap="truncate">
              <Text color={r.reason === 'answer' ? C.gate : C.warn}>{r.reason === 'answer' ? '✓ ' : '✗ '}</Text>
              <Text>{`last turn ${fmtDuration(r.durationMs)} · ${plural(r.agents, 'agent')} · ${plural(r.edits, 'edit')} · ${plural(r.errors, 'error')}`}</Text>
              {r.costDelta !== null ? <Text color={C.main}>{` · +${fmtUsd(r.costDelta)}`}</Text> : null}
            </Text>
          ) : (
            <Text color={C.faint}>no turn finished yet</Text>
          )}
          {isReview ? <Text color={C.arch}>{`${cfg.architectLabel.toLowerCase()} reviewing before done (inferred)`}</Text> : null}
        </Box>
      )
    }

    // ---- crew: Clawd crabs per loop, the agent tree, and the plan/doc graph
    const crab = (key: string, verb: Verb, size: 'big' | 'mini', color: string) =>
      hasClient ? (
        <els.Client key={`clawd-${size}-${key}`} module="./clawd-anim.tsx" props={{ verb, size, color, propColor: C.text }} />
      ) : size === 'mini' ? (
        <Text>
          <Text color={color}>{miniFrame(verb, 0)}</Text>
          <Text color={C.text}>{propFrame(verb, 0)}</Text>
        </Text>
      ) : (
        <Box flexDirection="column">
          {bigFrame(verb, 0).map((row, i) => (
            <Text>
              <Text color={color}>{row}</Text>
              <Text color={C.text}>{i === 0 ? propFrame(verb, 0) : '  '}</Text>
            </Text>
          ))}
        </Box>
      )
    const loopName = (key: string) => (key === 'main' ? 'main' : (cards.find(c => c.id === key)?.type ?? key.slice(0, 6)))
    const mainVerb: Verb = m.isRunning ? (ac.main?.verb ?? 'think') : ac.main?.verb === 'failed' ? 'failed' : r ? 'done' : 'wait'
    const crewPanel = (w: number) => {
      const plans = fl.filter(n => n.kind !== 'code')
      const code = fl.filter(n => n.kind === 'code')
      const rows: { prefix: string; card: AgentCard }[] = []
      const walk = (parent: string, depth: number) => {
        const kids = cards.filter(c => (pa[c.id] ?? 'main') === parent)
        kids.forEach((k, i) => {
          rows.push({ prefix: `${'  '.repeat(depth)}${i === kids.length - 1 ? '└─' : '├─'}`, card: k })
          walk(k.id, depth + 1)
        })
      }
      walk('main', 0)
      const edgeText = (by: Record<string, string>) =>
        Object.entries(by)
          .map(([k, op]) => `${loopName(k)}:${op}`)
          .join(' ')
      return (
        <Box flexDirection="column" borderStyle="round" borderColor={C.main} paddingX={1} width={w}>
          <Box justifyContent="space-between">
            <Text color={C.main} bold>
              crew
            </Text>
            <Text dimColor>{`${running.length} running · ${fl.length} files`}</Text>
          </Box>
          <Box columnGap={1}>
            {crab('main', mainVerb, 'big', C.main)}
            <Box flexDirection="column">
              <Text color={C.main} bold wrap="truncate">{`${modelName} · ${mainVerb}`}</Text>
              <Text wrap="truncate">{clip(ac.main?.target ?? '', Math.max(8, w - 18))}</Text>
              <Text dimColor wrap="truncate">{`${ac.main?.calls ?? 0} calls · ${m.steps} req`}</Text>
            </Box>
          </Box>
          {rows.slice(-8).map(({ prefix, card }) => {
            const verb = verbOfCard(card, ac[card.id])
            const tint = card.status === 'failed' || card.status === 'stopped' ? C.warn : card.status === 'done' ? C.gate : C.agent
            const what = card.status === 'running' ? `${verb} ${ac[card.id]?.target ?? ''}` : card.status
            return (
              <Box>
                <Text color={C.faint}>{prefix}</Text>
                {crab(card.id, verb, 'mini', tint)}
                <Text wrap="truncate">
                  <Text color={tint} bold>{` ${card.type}`}</Text>
                  <Text dimColor>{` ${clip(card.description, 18)}  `}</Text>
                  <Text>{clip(what, Math.max(6, w - prefix.length - 34))}</Text>
                </Text>
              </Box>
            )
          })}
          {rows.length > 8 ? <Text color={C.faint}>{`+${rows.length - 8} earlier agents`}</Text> : null}
          {plans.length > 0 ? <Text dimColor>plans & docs</Text> : null}
          {plans.slice(0, 6).map(n => (
            <Text wrap="truncate">
              <Text color={n.kind === 'plan' ? C.arch : C.amber}>{n.kind === 'plan' ? ' ■ plan ' : ' □ doc  '}</Text>
              <Text>{clip(n.path, Math.max(10, Math.floor(w / 2)))}</Text>
              <Text color={C.faint}>{' ◄─ '}</Text>
              <Text dimColor>{edgeText(n.by)}</Text>
            </Text>
          ))}
          {code.length > 0 ? (
            <Text dimColor wrap="truncate">
              {` · code ${code.length}: ${code
                .slice(0, 3)
                .map(n => `${n.path.split('/').pop() ?? n.path} ◄─ ${edgeText(n.by)}`)
                .join('  ')}`}
            </Text>
          ) : null}
        </Box>
      )
    }

    // ---- 3d: the web view, streamed into a Raster by bin/crew-3d.mjs
    const view3dPanel = (w: number) => {
      const Raster = 'Raster' in els ? els.Raster : null
      if (!v3.isOn || !Raster) {
        return (
          <Box flexDirection="column" width={w}>
            <Text color={C.main} bold>3d view</Text>
            <Text dimColor wrap="truncate">
              {Raster ? v3.status || 'off · /crew 3d' : 'the terminal draws the 3D view; here, /crew web opens it in a browser'}
            </Text>
          </Box>
        )
      }
      // A pane that changed width since the renderer started: restart it at the new size.
      const want = Math.max(20, Math.min(240, w))
      if (want !== v3.cols && !isRestarting3d) {
        isRestarting3d = true
        $.clock.after(400, () => void restart3d($, want, v3.rows, cfg.view3dFps, cfg.view3dMode))
      }
      const Image = 'Image' in els ? els.Image : null
      const picture =
        mode3d === 'image' && Image && lastImage ? (
          <Image
            key={RASTER_KEY}
            source={{ file: lastImage.path, format: 'rgb', width: lastImage.width, height: lastImage.height, generation: lastImage.gen }}
            columns={v3.cols}
            rows={v3.rows}
            alt="crew 3d view"
          />
        ) : (
          <Raster
            key={RASTER_KEY}
            columns={v3.cols}
            rows={v3.rows}
            cells={last3d && last3d.cols === v3.cols && last3d.rows === v3.rows ? last3d.cells : blankCells(v3.cols, v3.rows)}
          />
        )
      return (
        <Box flexDirection="column" width={w}>
          <Box justifyContent="space-between">
            <Text color={C.main} bold>3d view</Text>
            <Text dimColor wrap="truncate">{v3.status || 'drag rotate · wheel zoom · click pinch · stroke pet'}</Text>
          </Box>
          <Box width={v3.cols} height={v3.rows}>
            {picture}
            {hasClient ? (
              <Box position="absolute" top={0} left={0} width={v3.cols} height={v3.rows}>
                <els.Client key="input3d" module="./input3d.tsx" width={v3.cols} height={v3.rows} props={{ cols: v3.cols, rows: v3.rows }} />
              </Box>
            ) : null}
          </Box>
        </Box>
      )
    }

    // ---- log: whatever rows the other panels leave, 4 to 8
    // The main box's speed line and the gap above the log are a row each.
    const used = 2 + 5 + (m.speed ? 1 : 0) + 1 + (showArchitect ? 6 : 0) + 6 + (v.gateOpen ? 5 : 0) + (cards.length > cfg.maxCards ? 3 + Math.min(6, cards.length) : 8) + (expandedCard ? 8 : 0) + focusRows + (lp.length ? 1 : 0) + 3
    const bodyRows = e.props.scroll?.bodyRows ?? e.viewport?.rows ?? 40
    const nLog = logRows(bodyRows, used)
    const shownLines = (viewed ? lines.filter(l => l.agentId === viewed) : lines).slice(-nLog)
    const colorOf = (l: LogLine) =>
      l.kind === 'error' ? C.warn : l.kind === 'consult' ? C.arch : l.who === 'main' ? C.main : l.who === 'gate' ? C.gate : l.who === 'you' ? C.text : C.agent
    const logPanel = (w: number) => (
      <Box flexDirection="column" borderStyle="round" borderColor={C.faint} paddingX={1} marginTop={1} width={w}>
        <Text dimColor>{viewed ? 'session log · this agent' : 'session log'}</Text>
        {shownLines.length === 0 ? <Text color={C.faint}>nothing yet</Text> : null}
        {shownLines.map(l => (
          <Box>
            <Box width={9} flexShrink={0}>
              <Text color={C.faint}>{fmtClock(l.at)}</Text>
            </Box>
            <Box width={13} flexShrink={0}>
              <Text color={colorOf(l)} bold wrap="truncate">
                {l.who}
              </Text>
            </Box>
            <Text color={l.kind === 'error' ? C.warn : C.text} wrap="truncate">
              {l.text}
            </Text>
          </Box>
        ))}
      </Box>
    )

    const draw = (p: Panel, w: number) =>
      p === '3d'
        ? view3dPanel(w)
        : p === 'crew'
        ? crewPanel(w)
        : p === 'main'
        ? mainPanel(w)
        : p === 'architect'
          ? architectPanel(w)
          : p === 'gate'
            ? gatePanel(w)
            : p === 'agents'
              ? agentsPanel(w)
              : p === 'loops'
                ? loopsPanel(w)
                : p === 'receipt'
                  ? receiptPanel(w)
                  : logPanel(w)

    // Panels with the flow between them; the agents panel draws its own rails.
    const column = (ps: Panel[], w: number) => (
      <Box flexDirection="column" width={w}>
        {ps.map((p, i) => {
          const prev = ps[i - 1]
          const link =
            i === 0 || p === 'agents' || prev === 'agents' || p === 'log' || p === 'loops' || prev === 'loops' || p === 'crew' || prev === 'crew' || p === '3d' || prev === '3d'
              ? null
              : rail(`link-${p}`, p === 'architect' ? advising : m.isRunning, p === 'architect' ? C.arch : C.main, w)
          return (
            <Box flexDirection="column">
              {link}
              {draw(p, w)}
              {p === 'agents' ? expandedPanel(w) : null}
            </Box>
          )
        })}
      </Box>
    )

    // Desktop draws the agents' time axis as SVG under the panels.
    const svgLanes =
      e.surface !== 'terminal' && cards.length > 0
        ? (() => {
            const { Svg } = $.ui.resolve(e)
            const rowH = 18
            const pxW = 520
            const geo = lanes(cards.slice(-10), now, 100)
            const rects = cards
              .slice(-10)
              .map((c, i) => {
                const gm = geo[i]
                const x = 150 + ((gm?.before ?? 0) / 100) * (pxW - 160)
                const wpx = Math.max(3, ((gm?.bar ?? 1) / 100) * (pxW - 160))
                const fill = c.status === 'running' ? SVG_COLORS.running : c.status === 'done' ? SVG_COLORS.done : c.status === 'failed' ? SVG_COLORS.failed : SVG_COLORS.other
                const label = shorten(cardTitle(c), 22).replace(/[<&>]/g, '')
                return `<text x="4" y="${i * rowH + 13}" font-size="11" fill="${SVG_COLORS.label}">${label}</text><rect x="${x}" y="${i * rowH + 4}" width="${wpx}" height="10" rx="3" fill="${fill}"/>`
              })
              .join('')
            const svgH = Math.min(10, cards.length) * rowH + 4
            return (
              <Svg
                source={`<svg xmlns="http://www.w3.org/2000/svg" width="${pxW}" height="${svgH}" viewBox="0 0 ${pxW} ${svgH}">${rects}</svg>`}
                alt={`${cards.length} agents on a time axis`}
                width={pxW}
                height={svgH}
              />
            )
          })()
        : null

    // Inline above the prompt (the terminal's main screen), the pane is a summary of at most 8 rows.
    const isMini = layout === 'mini' || (layout === 'auto' && e.props.placement === 'inline')
    if (isMini) {
      const live = [...cards.filter(c => c.status === 'running'), ...cards.filter(c => c.status !== 'running').reverse()].slice(0, 3)
      const counts = ` ${s.rule} allowed · ${s.cleared} ${decider}${s.ask > 0 ? ` · ${s.ask} pending` : ''} · ${s.deny} denied`
      const strip = g.recent.slice(-Math.max(4, W - cfg.gateLabel.length - 1 - counts.length))
      const mg = u.pct !== null ? gauge(u.pct, 6) : null
      return (
        <Box flexDirection="column" width={W}>
          <Text wrap="truncate">
            <Text color={C.main}>{`${miniFrame(mainVerb, 0)}${propFrame(mainVerb, 0)} `}</Text>
            <Text color={C.main} bold>
              {modelName}
            </Text>
            <Text color={m.isRunning ? C.main : C.dim}>{m.isRunning ? ' ● working' : ' ○ idle'}</Text>
            {mg ? <Text dimColor> · ctx </Text> : null}
            {mg ? <Text color={(u.pct ?? 0) >= 80 ? C.warn : C.main}>{mg.on}</Text> : null}
            {mg ? <Text color={C.faint}>{mg.off}</Text> : null}
            {mg ? <Text>{` ${Math.round(u.pct ?? 0)}%`}</Text> : null}
            {u.compactions > 0 ? <Text color={C.amber}>{` ⟲${u.compactions}`}</Text> : null}
            {u.costUsd !== null ? <Text dimColor>{` · ${fmtUsd(u.costUsd)}`}</Text> : null}
            {showArchitect ? <Text color={C.arch}>{` · ${cfg.architectLabel.toLowerCase()} ${advising ? 'advising' : a.consults.length}`}</Text> : null}
          </Text>
          {strip.length > 0 ? (
            <Box>
              <Text dimColor>{`${cfg.gateLabel.toLowerCase()} `}</Text>
              {strip.map(c => (
                <Text color={verdictColor(c)} dimColor={c.inSubagent}>
                  {c.verdict === 'deny' ? '✗' : '■'}
                </Text>
              ))}
              <Text color={s.deny > 0 ? C.warn : s.ask > 0 ? C.amber : C.dim} wrap="truncate">
                {counts}
              </Text>
            </Box>
          ) : null}
          {live.map(c => (
            <Box>
              <Text color={statusColor(c)}>{`${glyph(c)} `}</Text>
              <Box width={Math.max(10, W - 30)}>
                <Text wrap="truncate">{cardTitle(c)}</Text>
              </Box>
              <Text dimColor>{c.steps > 0 ? ` ctx ${kTokens(c.ctx)} ` : ' '}</Text>
              {clock(`mini-clock-${c.id}`, c.spawnedAt, c.endedAt, C.dim)}
            </Box>
          ))}
          {cards.length > live.length ? (
            <Text color={C.faint} wrap="truncate">{`+${cards.length - live.length} more agents · /crew layout compact for all`}</Text>
          ) : null}
          {lp.length > 0 ? <Text dimColor>{`other loops ${lp.length} · ${lp.filter(l => isLoopActive(l, now)).length} active`}</Text> : null}
          {!m.isRunning && r ? (
            <Text dimColor wrap="truncate">
              {`last turn ${fmtDuration(r.durationMs)} · ${plural(r.agents, 'agent')} · ${plural(r.edits, 'edit')} · ${plural(r.errors, 'error')}${r.costDelta !== null ? ` · +${fmtUsd(r.costDelta)}` : ''}`}
            </Text>
          ) : null}
        </Box>
      )
    }

    const legend = fitLegend(
      [
        { label: 'main', color: C.main },
        { label: 'agents', color: C.agent },
        { label: cfg.gateLabel.toLowerCase(), color: C.gate },
        ...(showArchitect ? [{ label: cfg.architectLabel.toLowerCase(), color: C.arch }] : []),
      ],
      W,
    )

    const body = isWide ? (
      <Box flexDirection="column">
        {panels.includes('3d') ? view3dPanel(W) : null}
        <Box columnGap={2}>
          {column(panels.filter(p => p === 'main' || p === 'architect' || p === 'gate'), colW)}
          {column(panels.filter(p => p === 'crew' || p === 'agents' || p === 'loops' || p === 'receipt'), colW)}
        </Box>
        {panels.includes('log') ? logPanel(W) : null}
      </Box>
    ) : (
      column(panels, W)
    )

    // The scrollbar: measured again whenever what the tree holds changes shape.
    paneOffset = e.props.scroll?.offset ?? 0
    region3d = v3.isOn && panels[0] === '3d' && !isWide ? { top: 3, rows: v3.rows, cols: v3.cols } : null
    const sig = [panels.join(','), v3.isOn ? v3.rows : 0, isWide, W, bodyRows, cards.length, expandedCard ?? '', pf?.at ?? 0, v.gateOpen ?? '', lp.length, showArchitect, shownLines.length, m.speed ? 1 : 0, m.isRunning, !!r].join('|')
    if (sig !== paneSig) {
      paneSig = sig
      $.clock.after(80, () => void measurePane($))
    }
    const total = await read($, paneRows)
    const bar = isDock ? scrollbar(paneOffset, bodyRows, total) : null

    return (
      <Box width={W + (isDock ? 1 : 0)}>
      <Box flexDirection="column" width={W}>
        <Box justifyContent="center">
          <Text bold wrap="truncate">
            <Text>CREW</Text>
            <Text color={C.dim}> · </Text>
            <Text color={C.main}>{modelName.toUpperCase()}</Text>
            <Text>{m.isRunning ? ' WORKS' : ' IDLE'}</Text>
            {showArchitect ? <Text color={C.dim}> · </Text> : null}
            {showArchitect ? <Text color={C.arch}>{cfg.architectLabel}</Text> : null}
            {showArchitect ? <Text>{advising ? ' ADVISING' : ' ON CALL'}</Text> : null}
          </Text>
        </Box>
        <Box justifyContent="center" columnGap={2}>
          {legend.map(l => (
            <Text>
              <Text color={l.color}>■</Text>
              <Text dimColor>{` ${l.label}`}</Text>
            </Text>
          ))}
        </Box>
        {focusPanel(W)}
        {body}
        {svgLanes}
      </Box>
      {bar ? (
        <Box position="absolute" top={bar.top} left={W} width={1} height={bodyRows} flexDirection="column">
          {Array.from({ length: bodyRows }, (_, i) => {
            const isThumb = i >= bar.thumbTop && i < bar.thumbTop + bar.thumbLen
            return <Text color={isThumb ? C.main : C.faint}>{isThumb ? '┃' : '│'}</Text>
          })}
        </Box>
      ) : null}
      </Box>
    )
  })
}

files.hooks/deck/core.ts:
// Ported from Flightdeck by Stephen Casella (MIT, https://github.com/scasella/claude-flightdeck),
// see third_party/flightdeck-LICENSE.txt. Adapted for crew-graph.
// Pure data: defaults, reducers, formatting and layout math. Nothing here touches `$`, so every
// behaviour is testable directly (the test kit cannot raise a subagent's tool call or a
// permission check inside a call; these functions are what the hooks apply).
import type {
  AgentCard,
  Architect,
  Bucket,
  Check,
  Gate,
  Layout,
  LogLine,
  Loop,
  Main,
  Moment,
  Receipt,
  Roster,
  Tally,
  ToolNote,
  Turn,
  Usage,
  View,
} from '../../types'

export const SCHEMA_VERSION = 2

// ---------------------------------------------------------------- defaults

export const DEFAULT_MAIN: Main = { model: '', effort: '', mode: '', steps: 0, isRunning: false, speed: null }
export const DEFAULT_USAGE: Usage = {
  pct: null,
  tokens: null,
  window: 0,
  costUsd: null,
  limits: [],
  compactions: 0,
  lastCompactAt: null,
}
export const DEFAULT_ARCHITECT: Architect = { consults: [], ids: [], seen: [], lastAdvice: '' }
const ZERO: Tally = { rule: 0, ask: 0, cleared: 0, deny: 0 }
export const DEFAULT_GATE: Gate = { recent: [], totals: { file: ZERO, shell: ZERO, other: ZERO } }
export const DEFAULT_TURN: Turn = { edits: 0, errorStreak: 0, errors: 0, isReviewing: false, startedAt: 0, costAtStart: null }
export const DEFAULT_VIEW: View = { expanded: null, gateOpen: null, layout: null }
export const DEFAULT_ROSTER: Roster = { architectTypes: [] }

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)

/** A stored object merged over its defaults, so a value saved under an older shape still reads. */
export const normalize = <T extends object>(def: T, stored: unknown): T =>
  isObject(stored) ? ({ ...def, ...stored } as T) : def

/** A stored list, or empty when what is stored is not a list. */
export const listOf = <T>(stored: unknown): T[] => (Array.isArray(stored) ? (stored as T[]) : [])

export const normalizeGate = (stored: unknown): Gate => {
  const g = normalize(DEFAULT_GATE, stored)
  const totals = normalize(DEFAULT_GATE.totals, g.totals)
  return {
    recent: listOf<Check>(g.recent),
    totals: { file: normalize(ZERO, totals.file), shell: normalize(ZERO, totals.shell), other: normalize(ZERO, totals.other) },
  }
}

export const normalizeCard = (stored: unknown): AgentCard =>
  normalize<AgentCard>(
    {
      id: '',
      type: 'agent',
      model: '',
      description: '',
      status: 'running',
      spawnedAt: 0,
      endedAt: null,
      ctx: 0,
      out: 0,
      steps: 0,
      lastStop: null,
      tools: [],
      answer: '',
    },
    stored,
  )

export const normalizeLog = (stored: unknown): LogLine[] =>
  listOf<Record<string, unknown>>(stored).map(l => ({
    at: typeof l.at === 'number' ? l.at : 0,
    who: String(l.who ?? ''),
    text: String(l.text ?? ''),
    agentId: typeof l.agentId === 'string' ? l.agentId : null,
    kind: l.kind === 'error' || l.kind === 'consult' || l.kind === 'done' ? l.kind : 'info',
  }))

// ---------------------------------------------------------------- config

export type Panel = '3d' | 'main' | 'crew' | 'architect' | 'gate' | 'agents' | 'loops' | 'receipt' | 'log'
const PANELS: readonly Panel[] = ['3d', 'main', 'crew', 'architect', 'gate', 'agents', 'loops', 'receipt', 'log']

export type Config = {
  architect: RegExp
  architectLabel: string
  gateLabel: string
  panels: Panel[]
  motion: boolean
  moments: boolean
  matchDescriptions: boolean
  maxCards: number
  layout: Layout
  palette: Palette
  openOnStart: boolean
  statusLine: boolean
  /** crew-graph: start the browser view's data export when a session starts. */
  webOnStart: boolean
  /** crew-graph: start the desktop pet when a session starts. */
  petOnStart: boolean
  /** crew-graph: the in-pane 3D view's frame rate and height in rows. */
  view3dFps: number
  view3dRows: number
  view3dColumns: number
  view3dMode: 'auto' | 'cells' | 'image'
  /** crew-graph: who is drawn as which character, as written: "main=crab, Explore=bunny, *=random". Empty: every agent is a crab. */
  characters: string
  characterRules: CharacterRule[]
}

const safeRegExp = (source: string, fallback: string) => {
  try {
    return new RegExp(source || fallback, 'i')
  } catch {
    return new RegExp(fallback, 'i')
  }
}

/**
 * One `who=character` rule of the `characters` option. `character` is a character id, `random` (a stable pick by hash of the agent id)
 * or `auto` (the character whose traits fit the agent's role best).
 */
export type CharacterRule = [who: string, character: string]

/**
 * "main=crab, Explore=bunny; sonnet-coder=robot, *=random" -> [['main','crab'], ['Explore','bunny'], ['sonnet-coder','robot'], ['*','random']].
 * Parts are split by `,` `;` or a line break. A part without `=` is `*=<it>`, so `random`, `auto` or `bunny` alone work, and so does
 * `main=crab, random`; one with an empty side (`=x`, `y=`) is dropped. `random` and `auto` are kept apart (they are not the same).
 * The viewer (web/characters-core.js) reads the same text the same way; a test holds the two together.
 */
export const parseCharacterRules = (spec: unknown): CharacterRule[] => {
  const out: CharacterRule[] = []
  if (typeof spec !== 'string') return out
  for (const part of spec.split(/[,;\n]+/)) {
    const i = part.indexOf('=')
    if (i === 0) continue
    const who = i < 0 ? '*' : part.slice(0, i).trim()
    const ch = (i < 0 ? part : part.slice(i + 1)).trim()
    if (!who || !ch || who.length > 80 || ch.length > 80) continue
    out.push([who, /^random$/i.test(ch) ? 'random' : /^auto$/i.test(ch) ? 'auto' : ch])
  }
  return out.slice(0, 64)
}

/** The plugin's `/config` values, read leniently: anything malformed falls back to the default. */
export const parseConfig = (o: Readonly<Record<string, unknown>>): Config => {
  const str = (k: string, d: string) => (typeof o[k] === 'string' && o[k] !== '' ? (o[k] as string) : d)
  const bool = (k: string, d: boolean) => (typeof o[k] === 'boolean' ? (o[k] as boolean) : d)
  const panels = str('panels', PANELS.join(','))
    .split(',')
    .map(s => s.trim())
    .filter((p): p is Panel => (PANELS as readonly string[]).includes(p))
  const layout = str('layout', 'auto')
  const max = typeof o.maxCards === 'number' ? Math.round(o.maxCards) : 3
  return {
    architect: safeRegExp(str('architectPattern', ''), 'advisor|architect'),
    architectLabel: str('architectLabel', 'ARCHITECT'),
    gateLabel: str('gateLabel', 'GATE'),
    panels: panels.length > 0 ? [...new Set(panels)] : [...PANELS],
    motion: str('motion', 'while-active') !== 'off',
    moments: bool('moments', true),
    matchDescriptions: bool('matchDescriptions', false),
    maxCards: Math.min(6, Math.max(1, max)),
    layout: layout === 'compact' || layout === 'wide' || layout === 'mini' ? layout : 'auto',
    palette: str('palette', 'theme') === 'pastel' ? 'pastel' : 'theme',
    openOnStart: bool('openOnStart', true),
    statusLine: bool('statusLine', true),
    webOnStart: bool('webOnStart', false),
    petOnStart: bool('petOnStart', false),
    view3dFps: typeof o.view3dFps === 'number' ? Math.min(20, Math.max(1, Math.round(o.view3dFps))) : 10,
    view3dRows: typeof o.view3dRows === 'number' ? Math.min(60, Math.max(8, Math.round(o.view3dRows))) : 28,
    view3dColumns: typeof o.view3dColumns === 'number' ? Math.min(240, Math.max(40, Math.round(o.view3dColumns))) : 110,
    view3dMode: o.view3dMode === 'cells' || o.view3dMode === 'image' ? o.view3dMode : 'auto',
    characters: str('characters', ''),
    characterRules: parseCharacterRules(o.characters),
  }
}

// ---------------------------------------------------------------- palette

export type Palette = 'theme' | 'pastel'
export type Colors = Record<'main' | 'agent' | 'gate' | 'cleared' | 'arch' | 'amber' | 'warn' | 'dim' | 'faint' | 'text', string>

/**
 * `theme` names the person's own theme colours (they follow light, dark and colour-blind themes);
 * `pastel` is fixed hex tuned for dark terminals.
 */
export const PALETTES: Record<Palette, Colors> = {
  theme: {
    main: 'claude',
    agent: 'suggestion',
    gate: 'success',
    cleared: 'permission',
    arch: 'merged',
    amber: 'warning',
    warn: 'error',
    dim: 'inactive',
    faint: 'subtle',
    text: 'text',
  },
  pastel: {
    main: '#7dd3fc',
    agent: '#93c5fd',
    gate: '#86efac',
    cleared: '#5eead4',
    arch: '#c4b5fd',
    amber: '#fcd34d',
    warn: '#fca5a5',
    dim: '#6b7280',
    faint: '#3f4654',
    text: '#e5e7eb',
  },
}

/** SVG cannot name theme keys: mid-tone colours that read on light and dark backgrounds. */
export const SVG_COLORS = { running: '#3b82f6', done: '#16a34a', failed: '#dc2626', other: '#8b5cf6', label: '#6b7280' }

// ---------------------------------------------------------------- formatting

/** `claude-opus-5-5` → `Opus 5.5`; anything else is shown as given. */
/**
 * A model id as people say it, from any provider's spelling: `claude-opus-5-5[1m]` → `Opus 5.5 1M`,
 * `us.anthropic.claude-sonnet-4-5-20250929-v1:0` → `Sonnet 4.5`, `claude-3-5-haiku-20241022` →
 * `Haiku 3.5`. Anything else is shown as given, cut to 22 characters.
 */
export const prettyModel = (id: string) => {
  if (!id) return '—'
  const cap = (f: string) => f.charAt(0).toUpperCase() + f.slice(1)
  const big = /\[1m\]|-1m\b/i.test(id) ? ' 1M' : ''
  const now = /claude-([a-z]+)-(\d+)(?:-(\d{1,2}))?(?:-\d{8})?(?![\d])/i.exec(id)
  if (now?.[1] && !/^\d/.test(now[1])) return `${cap(now[1].toLowerCase())} ${now[2]}${now[3] ? `.${now[3]}` : ''}${big}`
  const old = /claude-(\d+)(?:-(\d))?-([a-z]+)/i.exec(id)
  if (old?.[3]) return `${cap(old[3].toLowerCase())} ${old[1]}${old[2] ? `.${old[2]}` : ''}${big}`
  return shorten(id, 22)
}

export const shorten = (s: string, n: number) => {
  const one = s.replace(/\s+/g, ' ').trim()
  return n <= 0 ? '' : one.length > n ? `${one.slice(0, Math.max(0, n - 1)).trimEnd()}…` : one
}

export const kTokens = (n: number) =>
  n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)}M` : n >= 1000 ? `${Math.round(n / 1000)}k` : String(n)

export const fmtDuration = (ms: number) => {
  const s = Math.max(0, Math.round(ms / 1000))
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  return m < 60 ? `${m}m${String(s % 60).padStart(2, '0')}s` : `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}m`
}

/** A running clock as the live cards draw it: m:ss, or XhYY past an hour. */
export const fmtTimer = (ms: number) => {
  const s = Math.max(0, Math.floor(ms / 1000))
  const m = Math.floor(s / 60)
  return m < 60 ? `${m}:${String(s % 60).padStart(2, '0')}` : `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}`
}

export const fmtClock = (ms: number) => (ms > 0 ? new Date(ms).toTimeString().slice(0, 8) : '--:--:--')

/** `1 error`, `2 errors`. */
export const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`

export const fmtUsd = (n: number) => (n >= 100 ? `$${Math.round(n)}` : `$${n.toFixed(2)}`)

/**
 * How fast a request answered, from three readings of the clock: when it was sent, when its first
 * piece of response arrived, and when it stopped. Null when no response came. `tokPerS` is null
 * when there is no usage or no time between the first piece and the stop to divide by.
 */
export const stepSpeed = (sentAt: number, firstAt: number | null, stopAt: number, outTokens: number | null) => {
  if (firstAt === null) return null
  const decodeMs = stopAt - firstAt
  return {
    ttftMs: Math.max(0, firstAt - sentAt),
    tokPerS: outTokens !== null && outTokens > 0 && decodeMs > 0 ? (outTokens * 1000) / decodeMs : null,
  }
}

/** `ttft 0.8s · 42 tok/s`; the rate is left off when it is unknown. */
export const fmtSpeed = (s: { ttftMs: number; tokPerS: number | null }) =>
  `ttft ${(s.ttftMs / 1000).toFixed(1)}s` + (s.tokPerS !== null ? ` · ${Math.round(s.tokPerS)} tok/s` : '')

/** A gauge of `width` cells: ▰ filled, ▱ empty. */
export const gauge = (pct: number, width: number) => {
  const full = Math.max(0, Math.min(width, Math.round((pct / 100) * width)))
  return { on: '▰'.repeat(full), off: '▱'.repeat(width - full) }
}

/** A rate-limit reading as the pane keeps it, its ISO reset time turned into ms since the epoch. */
export const limitOf = (r: { kind: string; percentUsed: number; resetsAt?: string }) => {
  const at = r.resetsAt ? Date.parse(r.resetsAt) : NaN
  return { kind: r.kind, pct: r.percentUsed, resetsAt: Number.isFinite(at) ? at : null }
}

/** Time left until a window resets, its two largest units: `25m`, `3h10m`, `4d2h`; empty when unknown or past. */
export const fmtResetIn = (resetsAt: number | null | undefined, now: number) => {
  if (resetsAt === null || resetsAt === undefined || resetsAt <= now) return ''
  const m = Math.max(1, Math.floor((resetsAt - now) / 60_000))
  const d = Math.floor(m / 1440)
  const h = Math.floor((m % 1440) / 60)
  if (d > 0) return `${d}d${h}h`
  return h > 0 ? `${h}h${String(m % 60).padStart(2, '0')}m` : `${m}m`
}

/** A rate-limit window's short name: `five_hour` → `5h`, `seven_day_opus` → `7d opus`. */
export const limitLabel = (kind: string) =>
  kind
    .replace(/five[_ -]?hours?/i, '5h')
    .replace(/seven[_ -]?days?/i, '7d')
    .replace(/[_-]+/g, ' ')
    .trim()

// ---------------------------------------------------------------- redaction

const SECRETS: [RegExp, string][] = [
  [/(authorization\s*[:=]\s*)(bearer\s+|basic\s+)?\S+/gi, '$1$2•••'],
  [/\b(bearer)\s+[A-Za-z0-9._~+/-]{8,}=*/gi, '$1 •••'],
  [/\b(sk|pk|rk|ghp|gho|ghs|github_pat|xox[abprs])[-_][A-Za-z0-9_-]{8,}/g, '•••'],
  [/((?:api[_-]?key|access[_-]?token|token|secret|password|passwd|pwd)\s*[=:]\s*)("[^"]*"|'[^']*'|\S+)/gi, '$1•••'],
  [/(--(?:token|password|api-key|secret)[= ])\S+/gi, '$1•••'],
  [/(\b[A-Z][A-Z0-9_]*(?:KEY|TOKEN|SECRET|PASSWORD)=)\S+/g, '$1•••'],
  [/(\b[a-z][a-z0-9+.-]*:\/\/[^\s/:@]+:)[^\s@]+@/gi, '$1•••@'],
]

/** What the gate drill-down may store: credentials masked before anything is written to state. */
export const redact = (s: string) => SECRETS.reduce((t, [re, to]) => t.replace(re, to), s)

// ---------------------------------------------------------------- tools and gate

const FILE_TOOLS = new Set(['Read', 'Edit', 'Write', 'NotebookEdit', 'Glob', 'Grep'])
const SHELL_TOOLS = new Set(['Bash', 'PowerShell'])
export const EDIT_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit'])

export const bucketOf = (tool: string): Bucket =>
  FILE_TOOLS.has(tool) ? 'file' : SHELL_TOOLS.has(tool) ? 'shell' : 'other'

/** One line saying what a call was about: its command, path or pattern; redacted. */
export const describeInput = (tool: string, input: unknown) => {
  const i = isObject(input) ? input : {}
  const path = typeof i.file_path === 'string' ? i.file_path.split(/[\\/]/).slice(-2).join('/') : ''
  const what =
    typeof i.command === 'string'
      ? i.command
      : path || (typeof i.pattern === 'string' ? i.pattern : typeof i.url === 'string' ? i.url : typeof i.description === 'string' ? i.description : '')
  return redact(what ? `${tool} → ${what}` : tool)
}

/** Keeps the last `max` checks, but never drops a pending ask: its settle must still find it. */
export const trimRecent = (list: Check[], max: number): Check[] => {
  let extra = list.length - max
  if (extra <= 0) return list
  const out: Check[] = []
  for (const c of list) {
    if (extra > 0 && c.verdict !== 'ask') {
      extra -= 1
      continue
    }
    out.push(c)
  }
  return out.slice(-max * 2)
}

export const recordCheck = (g: Gate, c: Check): Gate => {
  const t = g.totals[c.bucket]
  return {
    recent: trimRecent([...g.recent, c], 80),
    totals: { ...g.totals, [c.bucket]: { ...t, [c.verdict]: t[c.verdict] + 1 } },
  }
}

/** An `ask` settled by the call that followed it: it ran (cleared) or was refused (deny). */
export const settleCheck = (g: Gate, id: string, didRun: boolean): Gate => {
  const c = g.recent.find(r => r.id === id && r.verdict === 'ask')
  if (!c) return g
  const verdict = didRun ? 'cleared' : 'deny'
  const t = g.totals[c.bucket]
  return {
    recent: g.recent.map(r => (r === c ? { ...r, verdict } : r)),
    totals: { ...g.totals, [c.bucket]: { ...t, ask: Math.max(0, t.ask - 1), [verdict]: t[verdict] + 1 } },
  }
}

export const gateSummary = (g: Gate) => {
  const all = (['file', 'shell', 'other'] as const).reduce(
    (s, k) => ({
      rule: s.rule + g.totals[k].rule,
      ask: s.ask + g.totals[k].ask,
      cleared: s.cleared + g.totals[k].cleared,
      deny: s.deny + g.totals[k].deny,
    }),
    { ...ZERO },
  )
  return { ...all, total: all.rule + all.ask + all.cleared + all.deny }
}

// ---------------------------------------------------------------- turn and architect

/**
 * The turn after one tool call. Errors count in the main loop only (a subagent's failure is its
 * own); edits count from every loop, so delegated work still reaches "before done".
 */
export const afterCall = (t: Turn, c: { inSubagent: boolean; hasFailed: boolean; isEdit: boolean }): Turn => ({
  ...t,
  errorStreak: c.inSubagent ? t.errorStreak : c.hasFailed ? t.errorStreak + 1 : 0,
  errors: t.errors + (!c.inSubagent && c.hasFailed ? 1 : 0),
  edits: t.edits + (c.isEdit ? 1 : 0),
})

/** Which of the architect's three moments a consult falls at: an inference over this turn so far. */
export const momentOf = (t: Pick<Turn, 'edits' | 'errorStreak'>): Moment =>
  t.errorStreak >= 2 ? 'error repeats' : t.edits === 0 ? 'before a plan' : 'before done'

export const startConsult = (a: Architect, c: { id: string; at: number; moment: Moment; via: string }): Architect =>
  a.consults.some(x => x.id === c.id) ? a : { ...a, consults: [...a.consults, { ...c, endAt: null }].slice(-40) }

/** Ends the open consult (the latest without an end), or the one named. */
export const endConsult = (a: Architect, at: number, advice: string | null, id?: string): Architect => {
  const open = [...a.consults].reverse().find(c => c.endAt === null && (id === undefined || c.id === id))
  return {
    ...a,
    consults: a.consults.map(c => (c === open ? { ...c, endAt: at } : c)),
    lastAdvice: advice ?? a.lastAdvice,
  }
}

export const isAdvising = (a: Architect) => a.consults.some(c => c.endAt === null)

/** A one-row timeline of consults across `width` cells: ◆ a consult, ━ while it ran. */
export const consultTimeline = (a: Architect, now: number, width: number) => {
  if (a.consults.length === 0 || width < 4) return '─'.repeat(Math.max(0, width))
  const first = a.consults[0]?.at ?? now
  const span = Math.max(1, now - first)
  const cells = Array.from({ length: width }, () => '─')
  for (const c of a.consults) {
    const from = Math.min(width - 1, Math.floor(((c.at - first) / span) * (width - 1)))
    const to = Math.min(width - 1, Math.floor((((c.endAt ?? now) - first) / span) * (width - 1)))
    for (let i = from + 1; i <= to; i += 1) cells[i] = '━'
    cells[from] = '◆'
  }
  return cells.join('')
}

export const receiptOf = (t: Turn, o: { durationMs: number; agentsSince: number; costNow: number | null; reason: string }): Receipt => ({
  durationMs: o.durationMs,
  agents: o.agentsSince,
  edits: t.edits,
  errors: t.errors,
  costDelta: o.costNow !== null && t.costAtStart !== null && o.costNow - t.costAtStart >= 0.005 ? o.costNow - t.costAtStart : null,
  reason: o.reason,
})

// ---------------------------------------------------------------- agents and loops

type StepUsage = { input_tokens?: number; cache_read_input_tokens?: number; cache_creation_input_tokens?: number; output_tokens?: number } | null

/** A card after one of its model requests: its context is the latest step's whole input; output adds up. */
export const applyStep = (c: AgentCard, s: { model: string; usage: StepUsage; stopReason: string | null }): AgentCard => {
  const u = s.usage ?? {}
  const ctx = (u.input_tokens ?? 0) + (u.cache_read_input_tokens ?? 0) + (u.cache_creation_input_tokens ?? 0)
  return {
    ...c,
    model: c.model || s.model,
    steps: c.steps + 1,
    ctx: ctx > 0 ? ctx : c.ctx,
    out: c.out + (u.output_tokens ?? 0),
    lastStop: s.stopReason,
  }
}

export const noteTool = (c: AgentCard, n: ToolNote): AgentCard => ({ ...c, tools: [...c.tools, n].slice(-3) })

export const stepLoop = (loops: Loop[], id: string, at: number): Loop[] => {
  const found = loops.find(l => l.id === id)
  const next = found
    ? loops.map(l => (l === found ? { ...l, steps: l.steps + 1, lastAt: at } : l))
    : [...loops, { id, steps: 1, firstAt: at, lastAt: at, isDone: false }]
  return next.slice(-60)
}

export const LOOP_ACTIVE_MS = 15_000
export const isLoopActive = (l: Loop, now: number) => !l.isDone && now - l.lastAt < LOOP_ACTIVE_MS

/** Swimlane geometry: each agent's bar on one shared axis from the first spawn to now. */
export const lanes = (cards: AgentCard[], now: number, width: number) => {
  const start = Math.min(...cards.map(c => c.spawnedAt).filter(n => n > 0), now)
  const span = Math.max(1, now - start)
  return cards.map(c => {
    const from = Math.floor(((Math.max(c.spawnedAt, start) - start) / span) * width)
    const to = Math.max(from + 1, Math.ceil((((c.endedAt ?? now) - start) / span) * width))
    return { id: c.id, before: Math.min(from, width), bar: Math.min(to, width) - Math.min(from, width), after: width - Math.min(to, width) }
  })
}

// ---------------------------------------------------------------- layout

/** How many log lines fit: what the other panels leave, never fewer than 4 nor more than 8. */
export const logRows = (bodyRows: number, used: number) => Math.max(4, Math.min(8, bodyRows - used - 3))

/** Legend items that fit on one row of `width` cells, in order; the rest are dropped. */
export const fitLegend = <T extends { label: string }>(items: T[], width: number) => {
  const out: T[] = []
  let used = 0
  for (const it of items) {
    const w = it.label.length + 4
    if (used + w > width) break
    out.push(it)
    used += w
  }
  return out
}

/** A card's title row: the task in the agent's own words, the type only when there is none. */
export const cardTitle = (c: AgentCard) => c.description || c.type

/** A title split over two rows at a word boundary: `first` cells on row one, `rest` on row two. */
export const titleLines = (title: string, first: number, rest: number): [string, string] => {
  const t = title.replace(/\s+/g, ' ').trim()
  if (t.length <= first) return [t, '']
  const cut = t.lastIndexOf(' ', first)
  const at = cut > 0 ? cut : first
  return [t.slice(0, at).trim(), shorten(t.slice(at), rest)]
}

/**
 * What a turn's opening text was, for the log: the person's words, or for a turn the engine
 * opened with a tagged message (a subagent's hand-back, a task notification), that message's kind.
 */
export const promptLine = (text: string): { who: string; text: string } => {
  const tag = /^\s*<([a-z][\w-]*)/i.exec(text)?.[1]
  if (!tag) return { who: 'you', text: shorten(text, 70) }
  const from = /\bfrom="([^"]+)"/.exec(text)?.[1]
  return { who: 'engine', text: shorten(`${tag.replace(/[-_]/g, ' ')}${from ? ` from ${from.slice(0, 8)}` : ''}`, 70) }
}

/**
 * A subagent's hand-back message: who sent it and the first line of what it said. The report
 * follows a framing header in the message; without one, the first line after the opening tag.
 */
export const handbackOf = (text: string): { from: string; body: string } | null => {
  const from = /^\s*<agent-message\s+from="([^"]+)"/.exec(text)?.[1]
  if (!from) return null
  const afterHeader = text.split(/The report follows:\s*\n/)[1]
  const rest = afterHeader ?? text.replace(/^\s*<agent-message[^>]*>/, '')
  const body =
    rest
      .split('\n')
      .map(l => l.trim())
      .find(l => l && !l.startsWith('[') && !l.startsWith('<') && !l.startsWith('</')) ?? ''
  return body ? { from, body } : null
}

/** The advice line a pane shows for a report: its first real line, markdown markers stripped, cut to 160. */
export const adviceLine = (report: string) => {
  const first = report.split('\n').map(l => l.trim()).find(l => l && !l.startsWith('[') && !l.startsWith('<')) ?? ''
  return shorten(first.replace(/\*\*|__/g, '').replace(/^[#>*\s-]+/, ''), 160)
}

export const elapsedOf = (c: AgentCard, now: number) => (c.endedAt ?? now) - c.spawnedAt

files.hooks/characters.ts:
// The user's own characters: a folder of voxel packs (*.json) and skinned models (*.glb) that the viewer cannot list
// itself (a page on file:// cannot read a folder), so the mod scans it and writes what the page needs beside the page:
//   characters-user.js          the manifest; JSON packs are inlined, a GLB is listed by name
//   characters-glb/<id>.<n>.js  a GLB as base64 script parts (a page on file:// may not fetch a file, a script it may load)
// Pure apart from the `CharFs` it is handed, so the tests run it on a map.

export type CharFs = {
  list(path: string): Promise<{ name: string; kind: string; size: number; mtimeMs: number }[]>
  read(path: string): Promise<string>
  readBytes(path: string): Promise<string> // base64
  write(path: string, text: string): Promise<void>
  exists(path: string): Promise<boolean>
}

/** The characters that ship with the viewer (web/characters.js); a test keeps this list and that file in step. `traits`: the role words `auto` matches. */
export const BUILTIN_CHARACTERS: readonly { id: string; name: string; traits: readonly string[] }[] = [
  { id: 'crab', name: 'Clawd crab', traits: ['lead', 'main', 'generalist'] },
  { id: 'bunny', name: 'Mochi bunny', traits: ['docs', 'write', 'summarize', 'quick', 'web'] },
  { id: 'cat', name: 'Loaf cat', traits: ['explore', 'search', 'investigate', 'review', 'locate'] },
  { id: 'mochi', name: 'Mochi hamster', traits: ['plan', 'architect', 'design', 'think', 'advisor'] },
  { id: 'robot', name: 'Boxbot', traits: ['code', 'build', 'fix', 'test', 'implement'] },
]

/** "traits": ["Code", "test", ...] -> lower-case words, at most 16 of 1-24 letters, digits, - _ (web/characters-core.js reads them the same way). */
export const traitsOf = (list: unknown): string[] => {
  const out: string[] = []
  if (!Array.isArray(list)) return out
  for (const x of list) {
    const w = typeof x === 'string' ? x.trim().toLowerCase() : ''
    if (/^[a-z0-9_-]{1,24}$/.test(w) && !out.includes(w)) out.push(w)
    if (out.length >= 16) break
  }
  return out
}

/** `$.fs.read` and `$.fs.write` refuse over 4 MiB: a GLB that big cannot be embedded. */
export const HOST_FILE_MAX = 4 * 1024 * 1024
const PART_CHARS = 3_000_000
const MANIFEST_MAX = 3 * 1024 * 1024

// ---------------------------------------------------------------- pack problems
// What is wrong or missing in a user's pack, as { level, code, text, fix }: an error means the character is not drawn as the pack meant (a
// crab, nothing, a food it does not eat), a warning means it works but misses something. This is a twin of PROBLEM_TABLE / lintVoxel in
// web/characters-core.js (the page runs that one for GLBs and as a fallback); a test feeds both the same packs and holds them together.

export type PackProblem = { level: 'error' | 'warn'; code: string; text: string; fix: string }

/** The rig bones (web/characters-core.js RIG) and the built-in foods (web/tasks.js FOODS); a test keeps these lists and those in step. */
export const RIG_BONES: readonly string[] = ['root', 'body', 'head', 'earL', 'earR', 'eyeL', 'eyeR', 'mouth', 'armL', 'handL', 'armR', 'handR', 'legL1', 'legL2', 'legL3', 'legR1', 'legR2', 'legR3', 'tail']
export const FOOD_IDS: readonly string[] = ['fish', 'carrot', 'treat', 'seed', 'battery', 'ticket']
const EYE_VARIANTS = ['x', 'squint', 'happy', 'sleepy', 'dizzy']
const BOX_LIMIT = 400
const FOOD_BOX_LIMIT = 40

type Row = [level: 'error' | 'warn', text: (d?: string) => string, fix: (d?: string) => string]
const listOf = (a: string[]): string => a.slice(0, 4).map(x => `"${x}"`).join(', ') + (a.length > 4 ? ` and ${a.length - 4} more` : '')
const PROBLEM_TABLE: Record<string, Row> = {
  // errors
  unreadable: ['error', () => 'The file could not be read.', () => 'Check that it exists and is not locked by another program, then rescan.'],
  'bad-json': ['error', d => `Not valid JSON${d ? ` (${d})` : ''}, so it is skipped.`, () => 'Fix the syntax (a trailing comma or a missing quote is the usual cause) and rescan.'],
  'too-big': ['error', d => `Too big (${d || 'over 512 KiB'}), so it is skipped.`, () => `Use fewer boxes: a pack is meant to be small, up to ${BOX_LIMIT} boxes.`],
  'no-bones': ['error', () => 'There is no "bones" object, so nothing can be drawn.', () => 'Add "bones": { "body": { "boxes": [ { "size": [5,3,4], "at": [0,2,0], "color": "#88aaff" } ] } }.'],
  'nothing-drawn': ['error', () => 'No box is left to draw, so the character is invisible.', () => 'Give "body" (or another bone) at least one box: { "size": [w,h,d], "at": [x,y,z], "color": "#rrggbb" }.'],
  'food-bad': ['error', () => '"food" is not a built-in food or a list of boxes, so it eats the seed.', () => `Use one of ${FOOD_IDS.join(', ')}, or boxes: "food": { "boxes": [ ... ] }.`],
  'glb-failed': ['error', d => `The model could not be loaded${d ? ` (${d})` : ''}, so a crab is drawn instead.`, () => 'Export it again as a plain glTF binary (.glb) without Draco, Meshopt or KTX2 compression, then rescan.'],
  'glb-too-big': ['error', () => 'The model is over 4 MiB and this page cannot read it from the folder, so a crab is drawn instead.', () => 'Make it smaller than 4 MiB (fewer polygons, smaller textures), or use the desktop pet (/crew pet), which can read it.'],
  'glb-empty': ['error', () => 'The model has no geometry, so a crab is drawn instead.', () => 'Export the meshes together with the skeleton, not the armature alone.'],
  // warnings
  'food-none': ['warn', () => 'No "food", so it eats the seed.', () => 'Add "food": "seed" (or fish, carrot, treat, battery, ticket), or a list of boxes.'],
  'no-hands': ['warn', d => `No handL / handR ${d === 'glb' ? 'nodes' : 'bones'}, so items are held at the arm.`, d => (d === 'glb' ? 'Name the hand nodes handL and handR (Blender: Hand.L, Hand.R).' : 'Add "handL": { "parent": "armL", ... } and "handR": { "mirror": "handL" }.')],
  'no-mouth': ['warn', d => `No mouth ${d === 'glb' ? 'node' : 'bone'}, so it eats at the head.`, d => (d === 'glb' ? 'Name a node on the face "mouth".' : 'Add a "mouth" bone (parent "head") with a small box on the face.')],
  'no-traits': ['warn', () => 'No "traits", so auto never picks it by role.', () => 'Add "traits": ["code", "test"]; README.txt in the characters folder lists the words that count.'],
  'bone-unknown': ['warn', d => (/,| and /.test(d ?? '') ? `${d} are not rig bones, so they are skipped.` : `${d} is not a rig bone, so it is skipped.`), () => `Rename it to a rig bone (${RIG_BONES.join(' ')}) or remove it.`],
  'mirror-missing': ['warn', d => (/,| and /.test(d ?? '') ? `${d} mirror bones that are not defined, so they are skipped.` : `${d} mirrors a bone that is not defined, so it is skipped.`), () => 'Define the bone it mirrors, or give this one boxes of its own.'],
  'box-color': ['warn', d => `${d} no #rrggbb color and ${/^1 /.test(d ?? '') ? 'is' : 'are'} drawn light grey.`, () => 'Give each box "color": "#rrggbb" (or "@base" for the body color).'],
  'box-limit': ['warn', () => `More than ${BOX_LIMIT} boxes, so the rest are ignored.`, () => `Merge boxes or make them bigger; ${BOX_LIMIT} is the limit.`],
  'glb-large': ['warn', () => 'Over 4 MiB: the mod does not embed it, so the pet reads it from the folder and a browser may refuse.', () => 'Make it smaller than 4 MiB to work everywhere.'],
  'glb-unread': ['warn', () => 'The mod could not read the file, so the page will try the folder itself.', () => 'Check that it is not locked by another program, then rescan.'],
  'glb-no-rig': ['warn', () => 'No node is named like a rig bone, so only the whole model moves.', () => 'Name the nodes head, armL, handL, legL1 and so on (case and _ . - are ignored).'],
}
export const PACK_CODES: readonly string[] = Object.keys(PROBLEM_TABLE)

export function problem(code: string, detail?: string): PackProblem {
  const row = PROBLEM_TABLE[code]
  if (!row) throw new Error(`unknown pack problem code ${code}`)
  return { level: row[0], code, text: row[1](detail), fix: row[2](detail) }
}

/** 'error' if any problem is an error, 'warn' if there are only warnings, else 'ok'. */
export const statusOf = (list: readonly PackProblem[]): 'ok' | 'warn' | 'error' => (list.some(p => p.level === 'error') ? 'error' : list.length > 0 ? 'warn' : 'ok')

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null
const colorOk = (c: unknown): boolean => typeof c === 'string' && (/^#[0-9a-f]{6}$/i.test(c) || c === '@base')

/** A voxel pack as parsed JSON -> its problems; follows normalizeDef in web/characters-core.js step by step (same loops, same limits). */
export function lintVoxel(def: unknown): PackProblem[] {
  if (!isObj(def) || !isObj(def.bones)) return [problem('no-bones')]
  const bones = def.bones
  const errors: PackProblem[] = []
  const warns: PackProblem[] = []
  const unknown: string[] = []
  const missing: string[] = []
  const defined: Record<string, number> = {}
  let total = 0
  let over = false
  let drawn = 0
  let grey = 0
  const lintBox = (b: unknown): boolean => {
    if (!isObj(b)) return false
    if (!colorOk(b.color)) grey++
    return true
  }
  for (const name of Object.keys(bones)) {
    if (!RIG_BONES.includes(name)) {
      unknown.push(name)
      continue
    }
    const src = bones[name]
    if (!isObj(src) || typeof src.mirror === 'string') continue
    let n = 0
    for (const bx of Array.isArray(src.boxes) ? (src.boxes as unknown[]) : []) {
      if (total >= BOX_LIMIT) {
        over = true
        break
      }
      if (lintBox(bx)) {
        total++
        n++
      }
    }
    defined[name] = n
    drawn += n
  }
  for (const name of Object.keys(bones)) {
    const src = bones[name]
    if (!RIG_BONES.includes(name) || !isObj(src) || typeof src.mirror !== 'string') continue
    const from = Object.hasOwn(defined, src.mirror) ? defined[src.mirror] : undefined
    if (from == null) {
      missing.push(name)
      continue
    }
    defined[name] = from
    drawn += from
  }
  const eyes = def.eyes
  for (const v of EYE_VARIANTS) {
    if (!isObj(eyes) || !Array.isArray(eyes[v])) continue
    ;(eyes[v] as unknown[]).slice(0, 12).forEach(lintBox)
  }
  let food: 'none' | 'ok' | 'bad' = 'none'
  const f = def.food
  if (f != null) {
    food = 'bad'
    if (typeof f === 'string') {
      if (/^[a-z0-9_-]{1,24}$/.test(f.toLowerCase()) && FOOD_IDS.includes(f.toLowerCase())) food = 'ok'
    } else {
      const fl = Array.isArray(f) ? (f as unknown[]) : isObj(f) && Array.isArray(f.boxes) ? (f.boxes as unknown[]) : null
      if (fl) {
        let n = 0
        fl.slice(0, FOOD_BOX_LIMIT).forEach(bx => {
          if (lintBox(bx)) n++
        })
        if (n) food = 'ok'
      }
    }
  }
  if (drawn === 0) errors.push(problem('nothing-drawn'))
  if (food === 'bad') errors.push(problem('food-bad'))
  if (unknown.length) warns.push(problem('bone-unknown', listOf(unknown)))
  if (missing.length) warns.push(problem('mirror-missing', listOf(missing)))
  if (grey) warns.push(problem('box-color', `${grey} ${grey === 1 ? 'box has' : 'boxes have'}`))
  if (over) warns.push(problem('box-limit'))
  if (food === 'none') warns.push(problem('food-none'))
  if (defined.handL == null && defined.handR == null) warns.push(problem('no-hands'))
  if (defined.mouth == null) warns.push(problem('no-mouth'))
  if (traitsOf(def.traits).length === 0) warns.push(problem('no-traits'))
  return [...errors, ...warns]
}

export type UserChar =
  | { kind: 'voxel'; file: string; id: string; name: string; json: unknown; traits: string[] }
  | { kind: 'glb'; file: string; id: string; name: string; bytes: number; rev: string; parts: string[] | null }

/** One file of the folder: what it is, the id it has (or would have) and what is wrong with it. A pack that did not load has problems too. */
export type PackInfo = { file: string; id: string; kind: 'voxel' | 'glb'; problems: PackProblem[] }

/** `notes`: what is wrong with the folder itself (it cannot be read); a file's own problems are in `packs`. `at`: when it was scanned (ms). */
export type Scan = { chars: UserChar[]; notes: string[]; rev: string; packs: PackInfo[]; at?: number }

export const safeCharId = (s: string): string => {
  const id = s.replace(/\.[^.]*$/, '').replace(/[^A-Za-z0-9._-]+/g, '-').replace(/^[-.]+|[-.]+$/g, '').slice(0, 40)
  return id || 'character'
}

/**
 * Reads the folder. With `withData` a GLB is read and cut into base64 parts; without it only its size is looked at
 * (`/crew characters` just lists). Every .json and .glb gets an entry in `packs`, loaded or not, with its problems.
 */
export async function scanCharacters(fs: CharFs, folder: string, withData: boolean): Promise<Scan> {
  const notes: string[] = []
  const chars: UserChar[] = []
  const packs: PackInfo[] = []
  let entries: Awaited<ReturnType<CharFs['list']>> = []
  try {
    entries = await fs.list(folder)
  } catch {
    return { chars, notes: [`cannot read ${folder}`], rev: '0', packs }
  }
  const taken = new Set<string>(BUILTIN_CHARACTERS.map(c => c.id.toLowerCase()))
  const unique = (id: string) => {
    let out = id
    for (let n = 2; taken.has(out.toLowerCase()); n++) out = `${id.slice(0, 36)}-${n}`
    taken.add(out.toLowerCase())
    return out
  }
  let manifestBytes = 0
  for (const e of [...entries].sort((a, b) => (a.name < b.name ? -1 : 1))) {
    if (e.kind !== 'file') continue
    const low = e.name.toLowerCase()
    const path = `${folder}/${e.name}`
    if (low.endsWith('.json')) {
      // A pack that does not load keeps the id it would have had, so a rule that names it can be traced back to this file.
      const failed = (id: string, ...problems: PackProblem[]) => void packs.push({ file: e.name, id, kind: 'voxel', problems })
      if (e.size > 512 * 1024) {
        failed(safeCharId(e.name), problem('too-big', `${Math.round(e.size / 1024)} KiB, the limit is 512 KiB`))
        continue
      }
      let text: string
      try {
        text = await fs.read(path)
      } catch {
        failed(safeCharId(e.name), problem('unreadable'))
        continue
      }
      let json: unknown
      try {
        json = JSON.parse(text.replace(/^﻿/, ''))
      } catch (err) {
        failed(safeCharId(e.name), problem('bad-json', String((err as Error)?.message ?? '').replace(/ is not valid JSON$/, '').replace(/\s+/g, ' ').slice(0, 60)))
        continue
      }
      const j = json as { id?: unknown; name?: unknown; bones?: unknown } | null
      // A pack names itself ("id"); a file without a usable id takes its file name. A taken id (a built-in's, another pack's) gets a suffix.
      const wanted = j && typeof j === 'object' && typeof j.id === 'string' && /^[A-Za-z0-9._-]{1,40}$/.test(j.id) ? j.id : safeCharId(e.name)
      if (!j || typeof j !== 'object' || !j.bones || typeof j.bones !== 'object') {
        failed(wanted, problem('no-bones'))
        continue
      }
      const size = JSON.stringify(json).length
      if (manifestBytes + size > MANIFEST_MAX) {
        failed(wanted, problem('too-big', `the manifest would pass ${MANIFEST_MAX >> 20} MiB`))
        continue
      }
      const id = unique(wanted)
      manifestBytes += size
      chars.push({ kind: 'voxel', file: e.name, id, name: typeof j.name === 'string' && j.name ? j.name.slice(0, 60) : id, json: { ...(json as object), id }, traits: traitsOf((j as { traits?: unknown }).traits) })
      packs.push({ file: e.name, id, kind: 'voxel', problems: lintVoxel(json) })
    } else if (low.endsWith('.glb')) {
      const id = unique(safeCharId(e.name))
      const rev = `${e.size}-${Math.round(e.mtimeMs)}`
      const problems: PackProblem[] = []
      let parts: string[] | null = null
      if (e.size > HOST_FILE_MAX) {
        // not embedded: the page loads the file itself where it may (the desktop pet); a browser on file:// may refuse
        problems.push(problem('glb-large'))
      } else if (withData) {
        try {
          const b64 = await fs.readBytes(path)
          parts = []
          for (let i = 0; i < b64.length; i += PART_CHARS) parts.push(b64.slice(i, i + PART_CHARS))
        } catch {
          problems.push(problem('glb-unread'))
        }
      }
      chars.push({ kind: 'glb', file: e.name, id, name: id, bytes: e.size, rev, parts })
      packs.push({ file: e.name, id, kind: 'glb', problems })
    }
  }
  const rev = chars.map(c => `${c.id}:${c.kind === 'glb' ? c.rev : JSON.stringify(c.json).length}`).join('|') + `#${JSON.stringify(packs)}`
  return { chars, notes, rev: String(hash32(rev)), packs }
}

const hash32 = (s: string): number => {
  let h = 2166136261
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

/**
 * The manifest the page loads: `window.__crewUserCharacters` (what can be drawn), `window.__crewUserPacks` (every file with its problems,
 * also those that did not load), a revision it compares to know that something changed, and when the folder was scanned.
 */
export function manifestOf(scan: Scan): string {
  const list = scan.chars.map(c =>
    c.kind === 'voxel'
      ? { file: c.file, id: c.id, name: c.name, json: c.json }
      : { id: c.id, name: c.name, kind: 'glb', rev: c.rev, glb: { file: `characters/${c.file}`, parts: c.parts ? c.parts.length : 0, bytes: c.bytes } },
  )
  const at = typeof scan.at === 'number' ? `window.__crewUserScanned = ${Math.round(scan.at)};\n` : ''
  return `window.__crewUserCharacters = ${JSON.stringify(list)};\nwindow.__crewUserPacks = ${JSON.stringify(scan.packs)};\nwindow.__crewUserRev = ${JSON.stringify(scan.rev)};\n${at}`
}

/** Writes the manifest and the GLB parts into `dir` (the viewer's folder). */
export async function writeCharacters(fs: CharFs, dir: string, scan: Scan): Promise<void> {
  for (const c of scan.chars) {
    if (c.kind !== 'glb' || !c.parts) continue
    for (let i = 0; i < c.parts.length; i++) {
      await fs.write(`${dir}/characters-glb/${c.id}.${i}.js`, `window.__crewGlbPart(${JSON.stringify(c.id)}, ${i}, ${JSON.stringify(c.parts[i])});\n`)
    }
  }
  await fs.write(`${dir}/characters-user.js`, manifestOf(scan))
}

/** Creates the folder and its README.txt when they are not there. */
export async function ensureCharacterFolder(fs: CharFs, folder: string): Promise<void> {
  if (!(await fs.exists(`${folder}/README.txt`).catch(() => false))) await fs.write(`${folder}/README.txt`, CHAR_README)
}

export const CHAR_README = `crew-graph characters
=====================

Drop your own characters in this folder. The mod scans it when a session starts (/crew web, /crew pet)
and on  /crew characters reload ; a running pet or browser view picks the change up within a few seconds.
Then choose who is who with the "characters" option, for example
    main=crab, Explore=bunny, sonnet-coder=mymodel, *=auto
(left side: an agent id or type, "architect", or a prefix with * ; right side: a character id, "random" (a stable pick per agent)
or "auto" (the character whose traits fit the agent's role)). A part without "=" means "*=": "auto" alone is fine.
The pet's Settings window (tray icon or right-click menu, "Settings...") sets characters too: a default, a character per agent type,
or one agent, and it wins over the option. /crew characters lists what was found and what each agent would get.

Two kinds of file
-----------------

1. NAME.json   a voxel character: boxes on a named rig. Small, editable by hand.

   {
     "id": "mybot", "name": "My bot", "scale": 1,
     "bones": {
       "body":  { "boxes": [ { "size": [5,3,4], "at": [0,2,0], "color": "#88aaff" } ] },
       "head":  { "at": [0,3.5,0], "boxes": [ { "size": [4,3,4], "at": [0,1.5,0], "color": "#99bbff" } ] },
       "eyeL":  { "parent": "head", "at": [-1,1.6,2.1], "boxes": [ { "size": [0.8,1,0.3], "at": [0,0,0], "color": "#10131c" } ] },
       "eyeR":  { "mirror": "eyeL" },
       "armL":  { "at": [-2.8,2.5,0], "boxes": [ { "size": [1.4,1,1], "at": [-0.7,0,0], "color": "#88aaff" } ] },
       "armR":  { "mirror": "armL" },
       "legL1": { "at": [-1.2,0.5,0], "gait": 0, "boxes": [ { "size": [1.2,1,1.4], "at": [0,0,0], "color": "#5570c0" } ] },
       "legR1": { "mirror": "legL1", "gait": 2 }
     }
   }

   Units: the crab is 7 wide. x is to the right, y up, z toward the viewer (the character faces +z).
   "at" is relative to the bone's parent ("parent": a rig name, default "body"). A bone moves about its own origin,
   so put the origin where it should bend (an arm at the shoulder, an ear at its base). "mirror": "armL" copies a
   bone with x flipped. A box is { size, at, color } plus optional "rot": [rx,ry,rz] in radians, "unlit": true
   (an LED that ignores light) and "fixed": true (not tinted when the agent fails or is done).
   Colors are "#rrggbb"; "@base" is the body colour from "base": { "h":15, "s":0.7, "l":0.56, "spread":15 }.
   Optional: "eyes": { "x": [...], "squint": [...], "happy": [...], "sleepy": [...], "dizzy": [...] } = boxes for the
   LEFT eye in each expression (the right one is mirrored); without them the viewer draws default ones.
   Also optional: "props": { "page": {"at":[x,y,z]}, "hat": {"at":[x,y,z],"s":1}, "anten": {"at":[x,y,z],"spread":1.5} },
   "hit": { "y": 3, "r": 1 }, "shadow": [8,6], "travel": 1 (how far the eyes slide).
   "traits": ["code", "test", "cheerful"]: role words for "auto". An agent's role comes from its type (Explore, Plan, sonnet-coder,
   code-reviewer, general-purpose, ...), the words of its task and what it is doing; the character whose traits overlap the most is
   chosen (siblings are spread over equally good characters, and an agent keeps the character it was first given). Words that
   count: lead main generalist code build fix test implement run explore search investigate locate review docs write summarize
   quick web plan architect design think advisor. Other words are fine, they just never match.
   "food": "carrot": what this character works on and eats when the pet shows its tasks. A built-in (fish carrot treat seed battery
   ticket), or boxes like a bone: "food": { "boxes": [ { "size":[2.4,0.5,0.5], "at":[0,0,0], "color":"#e8e0d0" }, ... ] }, centred on 0,
   about 2.5 voxels long with the long side along x, at most 40 boxes. Without one (or with one that is not valid), the crab gets a fish,
   the bunny a carrot, the cat a treat stick, the hamster a sunflower seed, the robot a battery, and your own characters a sunflower seed
   (a .glb has no food of its own: it eats the seed).

   The rig (every bone is optional; an animation skips the bones a character lacks):
     root body head earL earR eyeL eyeR mouth armL handL armR handR legL1 legL2 legL3 legR1 legR2 legR3 tail

2. NAME.glb   a skinned model (glTF binary) whose bones (nodes) have those names. Case does not matter and _ . space
   - are ignored: "Head", "arm_L", "Arm.L", "mixamorig:Head" -> head, armL ... "left arm" and "L_Leg" work too.
   Bones the animation drives: head, ears, eyes, mouth, arms, hands, legs, tail (the model as a whole bobs, leans and squashes).
   Rotate the bones in the model's own rest pose: the viewer moves them relative to it.
   It is scaled to fit the crab's footprint (about 7 wide, 6.5 tall) and stood on the ground facing +z (a model whose eyes are
   at its back is turned around). Optional extra nodes next to the eye bones, named eyeL_happy, eyeL_x, eyeL_squint,
   eyeL_sleepy, eyeL_dizzy (and the same for eyeR), are shown instead of the eye for that expression.
   Draco, Meshopt and KTX2 compression are not supported. Files up to 4 MiB are embedded; a larger one is read from this
   folder by the page itself, which the desktop pet can do and a browser on file:// may refuse.

Problems
--------

A file that is wrong or misses something is not silently ignored: a character whose pack has problems wears a small badge over its head
(red "!" for an error, amber "!" for warnings only), its hover card lists the first three, and the pet's Settings window has a
"Character packs" section with every file, its status and what to change. /crew characters prints the same list. Errors: the file cannot be read
or parsed, a model fails to load (a crab is drawn), nothing is left to draw, an invalid "food". Warnings: no "food" (it eats the seed), no
hand bones or no mouth (items are held at the arm, it eats at the head), no "traits", boxes or bones that were dropped.
`

/** What `/crew characters` prints: the built-in and user characters, every pack with its problems and what to change, and the current assignment. `extra`: more lines (the pet's own settings, the agents' picks). */
export function describeCharacters(
  scan: Scan,
  spec: string,
  folder: string,
  rules: readonly (readonly [string, string])[],
  reloaded: boolean,
  extra: readonly string[] = [],
): string {
  const lines: string[] = []
  lines.push(`Built-in: ${BUILTIN_CHARACTERS.map(c => `${c.id} (${c.name}: ${c.traits.join(', ')})`).join('; ')}`)
  if (scan.chars.length === 0 && scan.packs.length === 0) lines.push(`Your characters: none yet. Put *.json (voxel) or *.glb (skinned) files in ${folder}; README.txt there says how.`)
  else {
    lines.push(`Your characters (${folder}):`)
    for (const c of scan.chars) {
      lines.push(
        c.kind === 'voxel'
          ? `  ${c.id}  voxel  ${c.file}${c.traits.length ? `  traits: ${c.traits.join(', ')}` : ''}`
          : `  ${c.id}  glb    ${c.file}  ${(c.bytes / 1048576).toFixed(1)} MiB  ${c.parts ? 'embedded' : 'read from the file'}`,
      )
    }
    // Every file with a problem, grouped by pack, worst first; a file that did not load is listed here and nowhere above.
    const bad = scan.packs.filter(p => p.problems.length > 0).sort((a, b) => Number(statusOf(b.problems) === 'error') - Number(statusOf(a.problems) === 'error'))
    const loaded = new Set(scan.chars.map(c => c.file))
    const sick = scan.packs.filter(p => !loaded.has(p.file))
    const oks = scan.packs.length - bad.length
    lines.push(bad.length === 0 ? `Pack problems: none (${oks} pack${oks === 1 ? '' : 's'} ok).` : `Pack problems (${bad.length} of ${scan.packs.length} pack${scan.packs.length === 1 ? '' : 's'}${oks > 0 ? `, ${oks} ok` : ''}):`)
    for (const p of bad) {
      lines.push(`  ${p.file}  ${statusOf(p.problems) === 'error' ? 'ERROR' : 'warnings'}${sick.includes(p) ? '  (not loaded)' : ''}  as "${p.id}"`)
      for (const pr of p.problems) {
        lines.push(`    ${pr.level === 'error' ? 'error' : 'warn '}  ${pr.text}`)
        lines.push(`           fix: ${pr.fix}`)
      }
    }
  }
  for (const n of scan.notes) lines.push(`  ! ${n}`)
  if (spec.trim() === '') lines.push('Assignment: no "characters" option set, so every agent is a crab (unless the pet\'s Settings say otherwise). Set it in /config, e.g. main=crab, Explore=bunny, *=auto')
  else {
    const ids = new Set([...BUILTIN_CHARACTERS.map(c => c.id.toLowerCase()), ...scan.chars.map(c => c.id.toLowerCase())])
    lines.push(`Assignment: ${spec.trim()}`)
    for (const [who, ch] of rules) {
      lines.push(`  ${who} -> ${ch === 'random' ? 'a stable pick by agent id' : ch === 'auto' ? 'the character whose traits fit the agent\'s role' : ids.has(ch.toLowerCase()) ? ch : `${ch} (not found: a crab)`}`)
    }
    lines.push('  anyone else -> a stable pick by agent id among all of the above')
  }
  lines.push(...extra)
  lines.push(reloaded ? 'Rescanned: a running pet or browser view picks the change up within a few seconds.' : '/crew characters reload rescans the folder.')
  return lines.join('\n')
}

// ---------------------------------------------------------------- `auto`: the character whose traits fit the agent's role
// A twin of roleOf / autoPick in web/characters-core.js (the pet runs that one); a test feeds both the same agents and holds them together.

export type RoleAgent = { id: string; type?: string; description?: string; verb?: string; isArchitect?: boolean; parentId?: string | null }
export type Traited = { id: string; traits: readonly string[] }
export type AutoPick = { id: string; why: string[]; parent: string }
export type AutoState = { locks: Map<string, AutoPick> }

const TYPE_ROLES: [RegExp, string[]][] = [
  [/plan|architect|advisor|design|strateg/, ['plan', 'architect', 'design', 'think', 'advisor']],
  [/explor|search|locat|scout|find|investig|research|survey/, ['explore', 'search', 'investigate', 'locate']],
  [/review|audit|critic|verif|inspect|lint/, ['review', 'investigate']],
  [/doc|writer|write|summar|readme|wiki|translat|scribe|changelog/, ['docs', 'write', 'summarize']],
  [/web|fetch|browse|crawl|scrape/, ['web', 'quick']],
  [/cod(e|er|ing)|implement|build|develop|\bdev\b|engineer|fix|debug|refactor|test|tdd|resolver/, ['code', 'build', 'fix', 'test', 'implement']],
  [/quick|fast|haiku|mini|lite/, ['quick']],
  [/general|purpose|orchestr|coordinat|manager|lead/, ['generalist', 'lead']],
]
const TEXT_ROLES: [RegExp, string[]][] = [
  [/\b(implement\w*|code|coding|refactor\w*|build|compile|migrat\w*)\b|구현|코드/, ['code', 'build', 'implement']],
  [/\b(fix\w*|bugs?|debug\w*|patch\w*|repair\w*)\b|수정|버그/, ['fix', 'code']],
  [/\b(tests?|testing|specs?)\b|테스트/, ['test']],
  [/\b(run|execute|npm|script)\b|실행/, ['run']],
  [/\b(review\w*|audit\w*|critique|verify|check\w*)\b|리뷰|검토/, ['review']],
  [/\b(search\w*|find|locate|grep|look ?up|map|trace|survey)\b|검색|탐색|찾/, ['search', 'locate', 'explore']],
  [/\b(investigat\w*|analy[sz]\w*|research\w*|explor\w*|explain\w*)\b|조사|분석/, ['investigate', 'explore']],
  [/\b(docs?|document\w*|readme|write|writing|changelog|guide|translat\w*)\b|문서|작성/, ['docs', 'write']],
  [/\b(summari[sz]\w*|summary|tl;?dr)\b|요약/, ['summarize']],
  [/\b(web|fetch|url|https?|browse)\b/, ['web']],
  [/\b(plan\w*|design\w*|architect\w*|strategy|propose)\b|계획|설계/, ['plan', 'design']],
]
const VERB_ROLES: Record<string, string[]> = {
  edit: ['code', 'fix', 'implement'],
  run: ['run', 'build', 'test'],
  read: ['explore', 'search'],
  search: ['search', 'explore', 'locate'],
  web: ['web'],
  plan: ['plan', 'design'],
  think: ['think'],
  spawn: ['lead'],
}
const W_TYPE = 3
const W_TEXT = 1.2
const W_VERB = 0.8
const W_REPEAT = 0.75

/** An agent's role as { word: weight }, from its type, its task text and its verb. */
export function roleOf(agent: RoleAgent): Record<string, number> {
  const w: Record<string, number> = {}
  const add = (words: string[], k: number) => words.forEach(x => (w[x] = (w[x] ?? 0) + k))
  const type = String(agent.type ?? '').toLowerCase()
  if (agent.id === 'main' || type === 'main') add(['lead', 'main', 'generalist'], W_TYPE)
  if (agent.isArchitect) add(['architect', 'plan', 'design', 'think', 'advisor'], W_TYPE)
  for (const [re, words] of TYPE_ROLES) {
    if (re.test(type)) {
      add(words, W_TYPE)
      break
    }
  }
  const text = String(agent.description ?? '').toLowerCase().slice(0, 300)
  for (const [re, words] of TEXT_ROLES) if (re.test(text)) add(words, W_TEXT)
  const v = agent.verb ? VERB_ROLES[agent.verb] : undefined
  if (v) add(v, W_VERB)
  return w
}

/** The best character for the role; the first pick of an agent is kept (state.locks); siblings that took a character make it a little less attractive. */
export function autoPick(chars: readonly Traited[], agent: RoleAgent, state: AutoState): AutoPick | null {
  if (chars.length === 0) return null
  const key = String(agent.id)
  const had = state.locks.get(key)
  if (had && chars.some(c => c.id === had.id)) return had
  const role = roleOf(agent)
  const parent = agent.parentId != null ? String(agent.parentId) : ''
  const taken: Record<string, number> = {}
  state.locks.forEach((v, k) => {
    if (k !== key && v.parent === parent) taken[v.id] = (taken[v.id] ?? 0) + 1
  })
  const rows = chars.map(c => {
    const hit = c.traits.filter(x => (role[x] ?? 0) > 0).sort((x, y) => (role[y] ?? 0) - (role[x] ?? 0))
    return { c, hit, fit: hit.reduce((s, x) => s + (role[x] ?? 0), 0) }
  })
  const top = Math.max(...rows.map(r => r.fit))
  const unit = top > 0 ? 0.2 * top : W_REPEAT
  let best: { id: string; why: string[]; score: number; tie: number } | null = null
  for (const { c, hit, fit } of rows) {
    const score = fit - unit * (taken[c.id] ?? 0)
    const tie = hash32(`${key}|${c.id}`)
    if (!best || score > best.score + 1e-9 || (Math.abs(score - best.score) <= 1e-9 && tie < best.tie)) best = { id: c.id, why: hit.slice(0, 3), score, tie }
  }
  const pick = { id: best!.id, why: best!.why, parent }
  state.locks.set(key, pick)
  return pick
}

/** The agents of a snapshot file (data.js / sessions/<id>.js); [] when the text is missing or not a snapshot. */
export function agentsFromDataJs(text: string | null | undefined): RoleAgent[] {
  const mark = '&& window.__crewUpdate('
  const at = typeof text === 'string' ? text.indexOf(mark) : -1
  if (!text || at < 0) return []
  try {
    const snap = JSON.parse(text.slice(at + mark.length, text.lastIndexOf(')'))) as { agents?: unknown }
    if (!Array.isArray(snap.agents)) return []
    return snap.agents
      .filter((a): a is Record<string, unknown> => !!a && typeof a === 'object' && typeof (a as { id?: unknown }).id === 'string')
      .map(a => ({
        id: String(a.id),
        type: typeof a.type === 'string' ? a.type : '',
        description: typeof a.description === 'string' ? a.description : '',
        verb: typeof a.verb === 'string' ? a.verb : '',
        isArchitect: a.isArchitect === true,
        parentId: typeof a.parentId === 'string' ? a.parentId : null,
      }))
  } catch {
    return []
  }
}

/** What `auto` would give each agent of the latest snapshot, with the reason (the pet keeps the first pick it made for an agent). */
export function describeAgentPicks(agents: readonly RoleAgent[], chars: readonly Traited[]): string[] {
  if (agents.length === 0) return []
  const state: AutoState = { locks: new Map() }
  const lines = ['Auto-match for the agents of the latest snapshot (the pet keeps the first pick it made):']
  for (const a of agents) {
    const p = autoPick(chars, a, state)
    if (!p) continue
    const label = a.id === 'main' ? 'main' : a.type || a.id
    lines.push(`  ${label}${a.description && a.id !== 'main' ? ` (${a.description.slice(0, 40)})` : ''} -> ${p.id}${p.why.length ? ` (matched: ${p.why.join(', ')})` : ' (no trait fits: a stable pick)'}`)
  }
  return lines
}

/** What the pet's own settings file says about characters, for `/crew characters`; tolerant of a missing or broken file. */
export function describePetSettings(raw: string | null | undefined): string[] {
  if (raw == null) {
    return ["Pet settings: none yet. The pet's Settings window (tray icon or right-click menu: Settings...) sets a default, a character per agent type, or one agent; it wins over the option."]
  }
  let j: unknown
  try {
    j = JSON.parse(raw.replace(/^\uFEFF/, ''))
  } catch {
    return ["Pet settings: overlay/pet-settings.json is not valid JSON, so the pet ignores it (it writes a fresh one when you change a setting in the pet's Settings window)."]
  }
  const o = (j && typeof j === 'object' ? j : {}) as { default?: unknown; types?: unknown; agents?: unknown }
  const pairs = (m: unknown): [string, string][] =>
    m && typeof m === 'object' && !Array.isArray(m) ? Object.entries(m as Record<string, unknown>).filter((e): e is [string, string] => typeof e[1] === 'string') : []
  const types = pairs(o.types)
  const agents = pairs(o.agents)
  const lines = ["Pet settings (overlay/pet-settings.json, set in the pet's Settings window; they win over the option):"]
  lines.push(`  default: ${typeof o.default === 'string' && o.default ? (o.default === 'auto' ? 'auto (match the role)' : o.default) : 'none (the option, else a crab)'}`)
  for (const [k, v] of types) lines.push(`  ${k === '*' ? 'any other type (*)' : k} -> ${v}`)
  if (agents.length > 0) lines.push(`  ${agents.length} agent${agents.length === 1 ? '' : 's'} with a character of their own`)
  return lines
}

